const c="008",n=8,t="https://zh.wikisource.org/zh-hant/史記三家註/卷008",e="https://zh.wikisource.org/zh-hant/史記/卷008",o=JSON.parse('[{"id":"a1","section":"高祖本紀第八","anchor":"高祖，","notes":[{"source":"集解","text":"《漢書音義》曰：「諱邦。」張晏曰：「禮《謚法》無『高』，以爲功最高而爲漢帝之太祖，故特起名焉。」"}]},{"id":"a2","section":"高祖本紀第八","anchor":"高祖，沛豐邑中陽里人，姓劉氏，","notes":[{"source":"集解","text":"李斐曰：「沛，小沛也。劉氏隨魏徙大梁，移在豐，居中陽里。」孟康曰：「後沛爲郡，豐爲縣。」"},{"source":"索隱","text":"按：高祖，劉累之後，別食邑於范，士會之裔，留秦不反，更爲劉氏。劉氏隨魏徙大梁，後居豐，今言「姓劉氏」者是。《左傳》「天子建德，因生以賜姓，胙之土，命之氏。諸侯以字爲謚，因以爲族」。說者以爲天子賜姓命氏，諸侯命族，族者氏之別名也。然則因生賜姓，若舜生姚墟，以爲姚姓，封之於虞，即號有虞氏是也。若其後子孫更不得賜姓，即遂以虞爲姓，云「姓虞氏」。今此云「姓劉氏」，亦其義也。故姓者，所以統繫百代，使不別也。氏者，所以別子孫之所出。又《系本》篇言姓則在上，言氏則在下，故《五帝本紀》云「禹姓姒氏，契姓子氏，弃姓姬氏」是也。按：漢改泗水爲沛郡，治相城，故注以沛爲小沛也。"}]},{"id":"a3","section":"高祖本紀第八","anchor":"高祖，沛豐邑中陽里人，姓劉氏，字季。","notes":[{"source":"索隱","text":"按：《漢書》「名邦，字季」，此單云字，亦又可疑。按：漢高祖長兄名伯，次名仲，不見別名，則季亦是名也。故項岱云「高祖小字季，即位易名邦，後因諱邦不諱季，所以季布猶稱姓也」。"}]},{"id":"a4","section":"高祖本紀第八","anchor":"高祖，沛豐邑中陽里人，姓劉氏，字季。父曰太公，","notes":[{"source":"索隱","text":"皇甫謐云：「名執嘉。」王符云：「太上皇名煓。」與湍同音。"},{"source":"正義","text":"春秋握成圖云：「劉媼夢赤鳥如龍，戲己，生執嘉。」"}]},{"id":"a5","section":"高祖本紀第八","anchor":"高祖，沛豐邑中陽里人，姓劉氏，字季。父曰太公，母曰劉媼。","notes":[{"source":"集解","text":"文穎曰：「幽州及漢中皆謂老嫗爲媼。」孟康曰：「長老尊稱也。左師謂太后曰『媼愛燕后賢長安君』。禮樂志『地神曰媼』。媼，母別名也，音烏老反。」"},{"source":"索隱","text":"韋昭云：「媼，婦人長老之稱。」皇甫謐云：「媼蓋姓王氏。」又據春秋握成圖以爲執嘉妻含始，遊洛池，生劉季。詩含神霧亦云。姓字皆非正史所出，蓋無可取。今近有人云「母溫氏」。貞時打得班固泗水亭長古石碑文，其字分明作「溫」字，云「母溫氏」。貞與賈膺復、徐彥伯、魏奉古等執對反覆，沈歎古人未聞，聊記異見，於何取實也？孟康注「地神曰媼」者，禮樂志云「后土富媼」，張晏曰「坤爲母，故稱媼」是也。"},{"source":"正義","text":"《帝王世紀》云：「漢昭靈后含始游洛池，有寶雞銜赤珠出炫日，后吞之，生高祖。」詩含神霧亦云。含始即昭靈后也。陳留風俗傳云：「沛公起兵野戰，喪皇妣於黃鄉，天下平定，使使者以梓宮招幽魂，於是丹蛇在水自灑，躍入梓宮，其浴處有遺髮，謚曰昭靈夫人。」漢儀注云：「高帝母起兵時死小黃城，後於小黃立陵廟。」《括地志》云：「小黃故城在汴州陳留縣東北三十三里。」顏師古云：「皇甫謐等妄引讖記，好奇騁博，強爲高祖父母名字，皆非正史所說，蓋無取焉。寧有劉媼本姓實存，史遷肯不詳載？即理而言，斷可知矣。」"}]},{"id":"a6","section":"高祖本紀第八","anchor":"劉媼嘗息大澤之陂，夢與神遇。是時雷電晦冥，太公往視，則見蛟龍於其上。","notes":[{"source":"索隱","text":"按：詩含神霧云「赤龍感女媼，劉季興」。又廣雅云「有鱗曰蛟龍」。"}]},{"id":"a7","section":"高祖本紀第八","anchor":"高祖爲人，隆準而龍顏，","notes":[{"source":"集解","text":"服虔曰：「準音拙。」應劭曰：「隆，高也。準，頰權準也。顏，頟顙也，齊人謂之顙，汝南、淮、泗之閒曰顏。」文穎曰：「準，鼻也。」"},{"source":"索隱","text":"李斐云：「準，鼻也。始皇蜂目長準，蓋鼻高起。」《爾雅》：「顏，額也。」文穎曰：「高祖感龍而生，故其顏貌似龍，長頸而高鼻。」"}]},{"id":"a8","section":"高祖本紀第八","anchor":"高祖爲人，隆準而龍顏，美須髯，左股有七十二黑子。","notes":[{"source":"正義","text":"《河圖》云：「帝劉季口角戴勝，斗胸，龜背，龍股，長七尺八寸。」《合誠圖》云：「赤帝體爲朱鳥，其表龍顏，多黑子。」按：左，陽也。七十二黑子者，赤帝七十二日之數也。木火土金水各居一方，一歲三百六十日，四方分之，各得九十日，土居中央，並索四季，各十八日，俱成七十二日，故高祖七十二黑子者，應火德七十二日之徵也。有一本「七十日」者，非也。許北人呼爲「黶子」，吳楚謂之「誌」。誌，記也。"}]},{"id":"a9","section":"高祖本紀第八","anchor":"高祖爲人，隆準而龍顏，美須髯，左股有七十二黑子。仁而愛人，喜施，","notes":[{"source":"正義","text":"喜，許記反。施，尸豉反。"}]},{"id":"a10","section":"高祖本紀第八","anchor":"人，隆準而龍顏，美須髯，左股有七十二黑子。仁而愛人，喜施，意豁如也。","notes":[{"source":"集解","text":"服虔曰：「豁，達也。」"}]},{"id":"a11","section":"高祖本紀第八","anchor":"仁而愛人，喜施，意豁如也。常有大度，不事家人生產作業。及壯，試爲吏，","notes":[{"source":"集解","text":"應劭曰：「試補吏。」"}]},{"id":"a12","section":"高祖本紀第八","anchor":"施，意豁如也。常有大度，不事家人生產作業。及壯，試爲吏，爲泗水亭長，","notes":[{"source":"正義","text":"秦法，十里一亭，十亭一鄉。亭長，主亭之吏。高祖爲泗水亭長也。《國語》有「寓室」，即今之亭也。亭長，蓋今里長也。民有訟諍，吏留平辨，得成其政。《括地志》云：「泗水亭在徐州沛縣東一百步，有高祖廟也。」"}]},{"id":"a13","section":"高祖本紀第八","anchor":"試爲吏，爲泗水亭長，廷中吏無所不狎侮。好酒及色。常從王媼、武負貰酒，","notes":[{"source":"集解","text":"韋昭曰：「貰，賒也。」"},{"source":"索隱","text":"鄒誕生貰音世，與《字林》聲韻並同。又音時夜反。廣雅云：「貰，賒也。」說文云：「貰，貸也。」臨淮有貰陽縣。《漢書功臣表》「貰陽侯劉纏」，而此紀作「射陽」，則「貰」亦「射」也。"}]},{"id":"a14","section":"高祖本紀第八","anchor":"負貰酒，醉臥，武負、王媼見其上常有龍，怪之。高祖每酤留飲，酒讎數倍。","notes":[{"source":"集解","text":"如淳曰：「讎亦售。」"},{"source":"索隱","text":"樂彥云借「讎」爲「售」，蓋古字少，假借耳。今亦依字讀。蓋高祖大度，既貰飲，且讎其數倍價也。"}]},{"id":"a15","section":"高祖本紀第八","anchor":"有龍，怪之。高祖每酤留飲，酒讎數倍。及見怪，歲竟，此兩家常折券弃責。","notes":[{"source":"索隱","text":"《周禮》小司寇云：「聽稱責以傅別。」鄭司農云：「傅別，券書也。」康成云：「傅別，謂大手書於札中而別之也。」然則古用簡札書，故可折。至歲終總弃不責也。"}]},{"id":"a16","section":"高祖本紀第八","anchor":"高祖常繇咸陽，","notes":[{"source":"集解","text":"應劭曰：「徭役也。」"},{"source":"索隱","text":"韋昭云：「秦所都，武帝更名渭城。」應劭云：「今長安也。」按：《關中記》云「孝公都咸陽，今渭城是，在渭北。始皇都咸陽，今城南大城是也」。名咸陽者，山南曰陽，水北亦曰陽，其地在渭水之北，又在九嵕諸山之南，故曰咸陽。"}]},{"id":"a17","section":"高祖本紀第八","anchor":"高祖常繇咸陽，縱觀，觀秦皇帝，","notes":[{"source":"正義","text":"包愷云：「上音館，下音官。恣意，故縱觀也。」"}]},{"id":"a18","section":"高祖本紀第八","anchor":"單父人呂公","notes":[{"source":"集解","text":"《漢書音義》曰：「單音善。父音斧。」"},{"source":"索隱","text":"韋昭云：「單父，縣名，屬山陽。」崔浩云：「史失其名，但舉姓而言公。」又按：《漢書》舊儀云「呂公，汝南新蔡人」。　又相經云「魏人呂公，名文，字叔平」也。"}]},{"id":"a19","section":"高祖本紀第八","anchor":"令，避仇從之客，因家沛焉。沛中豪桀吏聞令有重客，皆往賀。蕭何爲主吏，","notes":[{"source":"集解","text":"孟康曰：「主吏，功曹也。」"}]},{"id":"a20","section":"高祖本紀第八","anchor":"仇從之客，因家沛焉。沛中豪桀吏聞令有重客，皆往賀。蕭何爲主吏，主進，","notes":[{"source":"集解","text":"文穎曰：「主賦斂禮進，爲之帥。」"},{"source":"索隱","text":"鄭氏云：「主賦斂禮錢也。」顏師古曰：「進者，會禮之財。字本作『賮』，聲轉爲『進』。『宣帝數負進』，義與此同。」"}]},{"id":"a21","section":"高祖本紀第八","anchor":"家沛焉。沛中豪桀吏聞令有重客，皆往賀。蕭何爲主吏，主進，令諸大夫曰：","notes":[{"source":"正義","text":"大夫，客之貴者總稱之。"}]},{"id":"a22","section":"高祖本紀第八","anchor":"諸大夫曰：「進不滿千錢，坐之堂下。」高祖爲亭長，素易諸吏，乃紿爲謁曰","notes":[{"source":"集解","text":"應劭曰：「紿，欺也。音殆。」"},{"source":"索隱","text":"韋昭云：「紿，詐也。」劉氏云：「紿，欺負也。」何休云：「紿，疑也。」謂高祖素狎易諸吏，乃詐爲謁。謁謂以札書姓名，若今之通刺，而兼載錢穀也。"}]},{"id":"a23","section":"高祖本紀第八","anchor":"引入坐。蕭何曰：「劉季固多大言，少成事。」高祖因狎侮諸客，遂坐上坐，","notes":[{"source":"正義","text":"上在果反。下在臥反。"}]},{"id":"a24","section":"高祖本紀第八","anchor":"蕭何曰：「劉季固多大言，少成事。」高祖因狎侮諸客，遂坐上坐，無所詘。","notes":[{"source":"正義","text":"音丘忽反。"}]},{"id":"a25","section":"高祖本紀第八","anchor":"：「劉季固多大言，少成事。」高祖因狎侮諸客，遂坐上坐，無所詘。酒闌，","notes":[{"source":"集解","text":"文穎曰：「闌言希也。謂飲酒者半罷半在，謂之闌。」"}]},{"id":"a26","section":"高祖本紀第八","anchor":"少成事。」高祖因狎侮諸客，遂坐上坐，無所詘。酒闌，呂公因目固留高祖。","notes":[{"source":"正義","text":"不敢對眾顯言，故目動而留之。"}]},{"id":"a27","section":"高祖本紀第八","anchor":"無所詘。酒闌，呂公因目固留高祖。高祖竟酒，後。呂公曰：「臣少好相人，","notes":[{"source":"集解","text":"張晏曰：「古人相與語多自稱臣，自卑下之道，若今人相與語皆自稱僕。」"}]},{"id":"a28","section":"高祖本紀第八","anchor":"，後。呂公曰：「臣少好相人，相人多矣，無如季相，願季自愛。臣有息女，","notes":[{"source":"正義","text":"息，生也。謂所生之女也。"}]},{"id":"a29","section":"高祖本紀第八","anchor":"「此非兒女子所知也。」卒與劉季。呂公女乃呂后也，生孝惠帝、魯元公主。","notes":[{"source":"集解","text":"服虔曰：「元，長也。食邑於魯。」韋昭曰：「元，謚也。」"},{"source":"正義","text":"漢制，帝女曰「公主」，儀比諸侯；姊妹曰「長公主」，儀比諸侯王；姑曰「大長公主」，儀比諸侯王。"}]},{"id":"a30","section":"高祖本紀第八","anchor":"高祖爲亭長時，常告歸之田。","notes":[{"source":"集解","text":"服虔曰：「告音如『嗥呼』之『嗥』。」李斐曰：「休謁之名也。吉曰告，凶曰寧。」孟康曰：「古者名吏休假曰告。告又音嚳。漢律，吏二千石有予告、賜告。予告者，在官有功最，法所當得者也。賜告者，病滿三月當免，天子優賜，復其告，使得帶印紱，將官屬，歸家治疾也。」"},{"source":"索隱","text":"韋昭云：「告，請歸乞假也。音『告語』之『告』。故《戰國策》曰『商君告歸』，延篤以爲告歸，今之歸寧也。」劉伯莊、顏師古並音古篤反，非號嚳兩音也。按：東觀漢記田邑傳云「邑年三十，歷卿大夫，號歸罷，厭事，少所嗜欲」。尋號與嗥同，古者當有此語，故服氏云「如號呼之號」，音豪。今以服虔雖據田邑「號歸」，亦恐未得。然此「告」字當音誥，誥號聲相近，故後「告歸」「號歸」遂變耳。"}]},{"id":"a31","section":"高祖本紀第八","anchor":"亭長時，常告歸之田。呂后與兩子居田中耨，有一老父過請飲，呂后因餔之。","notes":[{"source":"正義","text":"必捕反，以食飼人也。父本請飲，呂后因飼之。《國語》云：「國中童子無不餔。」"}]},{"id":"a32","section":"高祖本紀第八","anchor":"高祖爲亭長，乃以竹皮爲冠，令求盜之薛治之，","notes":[{"source":"集解","text":"應劭曰：「以竹始生皮作冠，今鵲尾冠是也。求盜者，舊時亭有兩卒，其一爲亭父，掌開閉埽除，一爲求盜，掌逐捕盜賊。薛，魯國縣也。有作冠師，故往治之。」"},{"source":"索隱","text":"應劭云：「一名『長冠』。側竹皮裹以縱前，高七寸，廣三寸，如板。」又蔡邕獨斷云：「長冠，楚制也。高祖以竹皮爲之，謂之『劉氏冠』。」司馬彪輿服志亦以「劉氏冠」爲鵲尾冠也。應劭云：「舊亭卒名『弩父』，陳、楚謂之『亭父』，或云『亭部』，淮、泗謂之『求盜』也。」"}]},{"id":"a33","section":"高祖本紀第八","anchor":"高祖爲亭長，乃以竹皮爲冠，令求盜之薛治之，時時冠之，","notes":[{"source":"正義","text":"音館，下同。"}]},{"id":"a34","section":"高祖本紀第八","anchor":"長，乃以竹皮爲冠，令求盜之薛治之，時時冠之，及貴常冠，所謂「劉氏冠」","notes":[{"source":"正義","text":"音官。顏師古云：「後號爲『劉氏冠』。其後詔曰『爵非公乘以上下得冠劉氏冠』，即此也。」"}]},{"id":"a35","section":"高祖本紀第八","anchor":"高祖以亭長爲縣送徒酈山，徒多道亡。自度比至皆亡之，","notes":[{"source":"正義","text":"度，田洛反。比，必寐反。"}]},{"id":"a36","section":"高祖本紀第八","anchor":"徒。曰：「公等皆去，吾亦從此逝矣！」徒中壯士願從者十餘人。高祖被酒，","notes":[{"source":"正義","text":"被，加也。"}]},{"id":"a37","section":"高祖本紀第八","anchor":"曰：「公等皆去，吾亦從此逝矣！」徒中壯士願從者十餘人。高祖被酒，夜徑","notes":[{"source":"索隱","text":"舊音經。按：廣雅云「徑，斜過也」。《字林》云「徑，小道也，音古定反」。言酒後放徒，夜徑行澤中，不敢由正路，且從而求疾也。"}]},{"id":"a38","section":"高祖本紀第八","anchor":"亦從此逝矣！」徒中壯士願從者十餘人。高祖被酒，夜徑澤中，令一人行前。","notes":[{"source":"正義","text":"行音下孟反。"}]},{"id":"a39","section":"高祖本紀第八","anchor":"餘人。高祖被酒，夜徑澤中，令一人行前。行前者還報曰：「前有大蛇當徑，","notes":[{"source":"索隱","text":"音逕。鄭玄曰：「步道曰徑也。」"}]},{"id":"a40","section":"高祖本紀第八","anchor":"有大蛇當徑，願還。」高祖醉，曰：「壯士行，何畏！」乃前，拔劍擊斬蛇。","notes":[{"source":"索隱","text":"漢舊儀云「斬蛇劍長七尺」。又高祖云「吾以布衣提三尺劍取天下」。二文不同者，崔豹古今注「當高祖爲亭長，理應提三尺劍耳；及貴，當別得七尺寶劍」，故舊儀因言之。"},{"source":"正義","text":"按：其蛇大，理須別求是劍斬之。三尺劍者，常佩之劍。《括地志》云：「斬蛇溝源出徐州豐縣中平地，故老云高祖斬蛇處，至縣西十五里入泡水也。」"}]},{"id":"a41","section":"高祖本紀第八","anchor":"願還。」高祖醉，曰：「壯士行，何畏！」乃前，拔劍擊斬蛇。蛇遂分爲兩，","notes":[{"source":"索隱","text":"謂斬蛇分爲兩段也。"}]},{"id":"a42","section":"高祖本紀第八","anchor":"嫗子何爲見殺？」嫗曰：「吾，白帝子也，化爲蛇，當道，今爲赤帝子斬之，","notes":[{"source":"集解","text":"應劭曰：「秦襄公自以居西戎，主少昊之神，作西畤，祠白帝。至獻公時櫟陽雨金，以爲瑞，又作畦畤，祠白帝。少昊，金德也。赤帝堯後，謂漢也。殺之者，明漢當滅秦也。秦自謂水，漢初自謂土，皆失之。至光武乃改定。」"},{"source":"索隱","text":"按：太康《地理志》云「畤在櫟陽故城內。其畤如畦，故曰畦畤」。畦音戶圭反。應注云「秦自謂水」者，按秦文公獲黑龍，命河爲德水是也。又按：《春秋合誠圖》云「水神哭，子褒敗」。宋均以爲高祖斬白蛇而神母哭，則此母水精也。此皆謬說。又注云「至光武乃改」者，謂改漢爲火德，秦爲金德，與雨金及赤帝子之理合也。"}]},{"id":"a43","section":"高祖本紀第八","anchor":"子也，化爲蛇，當道，今爲赤帝子斬之，故哭。」人乃以嫗爲不誠，欲告之，","notes":[{"source":"集解","text":"徐廣曰：「一作『苦』。」"},{"source":"索隱","text":"《漢書》作「苦」，謂欲困苦辱之。一本或作「笞」。說文云：「笞，擊也。」"}]},{"id":"a44","section":"高祖本紀第八","anchor":"子斬之，故哭。」人乃以嫗爲不誠，欲告之，嫗因忽不見。後人至，高祖覺。","notes":[{"source":"索隱","text":"包愷、劉伯莊音古孝反。"}]},{"id":"a45","section":"高祖本紀第八","anchor":"欲告之，嫗因忽不見。後人至，高祖覺。後人告高祖，高祖乃心獨喜，自負。","notes":[{"source":"集解","text":"應劭曰：「負，恃也。」"},{"source":"索隱","text":"晉灼云：「自恃斬蛇事。」"}]},{"id":"a46","section":"高祖本紀第八","anchor":"秦始皇帝常曰「東南有天子氣」，於是因東游以厭之。","notes":[{"source":"索隱","text":"厭音一涉反，又一冉反。廣雅云：「厭，鎮也。」"}]},{"id":"a47","section":"高祖本紀第八","anchor":"子氣」，於是因東游以厭之。高祖即自疑，亡匿，隱於芒、碭山澤巖石之閒。","notes":[{"source":"集解","text":"徐廣曰：「芒，今臨淮縣也。碭縣在梁。」駰案：應劭曰「二縣之界有山澤之固，故隱於其閒也」。"},{"source":"正義","text":"《括地志》云：「宋州碭山縣在州東一百五十里，本漢碭縣也。碭山在縣東。」"}]},{"id":"a48","section":"高祖本紀第八","anchor":"之閒。呂后與人俱求，常得之。高祖怪問之。呂后曰：「季所居上常有雲氣，","notes":[{"source":"正義","text":"京房易（兆）〔飛〕候云：「何以知賢人隱？（顏）師（古）曰：『四方常有大雲，五色具而不雨，其下有賢人隱矣。』」故呂后望雲氣而得之。"}]},{"id":"a49","section":"高祖本紀第八","anchor":"秦二世元年","notes":[{"source":"集解","text":"徐廣曰：「高祖時年四十八。」"},{"source":"索隱","text":"應劭云：「始皇欲以一至萬，示不相襲。始者一，故至子稱二世。」崔浩云：「二世，始皇子胡亥。」又按：善文稱隱士云「趙高爲二世殺十七兄而立今王」，則二世是第十八子也。"}]},{"id":"a50","section":"高祖本紀第八","anchor":"秦二世元年秋，陳勝等起蘄，","notes":[{"source":"索隱","text":"蘄，縣名，屬沛，音機，又音旂。"}]},{"id":"a51","section":"高祖本紀第八","anchor":"。諸郡縣皆多殺其長吏以應陳涉。沛令恐，欲以沛應涉。掾、主吏蕭何、曹參","notes":[{"source":"索隱","text":"按：《漢書》蕭、曹傳，參爲獄掾，何爲主吏也。"}]},{"id":"a52","section":"高祖本紀第八","anchor":"，今欲背之，率沛子弟，恐不聽。願君召諸亡在外者，可得數百人，因劫眾，","notes":[{"source":"索隱","text":"說文云「以力脅之云劫」也。"}]},{"id":"a53","section":"高祖本紀第八","anchor":"數百人，因劫眾，眾不敢不聽。」乃令樊噲召劉季。劉季之眾已數十百人矣。","notes":[{"source":"索隱","text":"《漢書》作「數百人」。劉伯莊云「言數十人或至百人」，則是百人已下也。"}]},{"id":"a54","section":"高祖本紀第八","anchor":"。沛令後悔，恐其有變，乃閉城城守，欲誅蕭、曹。蕭、曹恐，踰城保劉季。","notes":[{"source":"集解","text":"韋昭曰：「以爲保障。」"}]},{"id":"a55","section":"高祖本紀第八","anchor":"上，謂沛父老曰：「天下苦秦久矣。今父老雖爲沛令守，諸侯並起，今屠沛。","notes":[{"source":"索隱","text":"按：范曄云「剋城多所誅殺，故云屠也」。"}]},{"id":"a56","section":"高祖本紀第八","anchor":"季，欲以爲沛令。劉季曰：「天下方擾，諸侯並起，今置將不善，壹敗塗地。","notes":[{"source":"索隱","text":"言一朝破敗，使肝腦塗地。"}]},{"id":"a57","section":"高祖本紀第八","anchor":"曰：「天下方擾，諸侯並起，今置將不善，壹敗塗地。吾非敢自愛，恐能薄，","notes":[{"source":"正義","text":"能，才能也。高祖謙言材能薄劣，不能完全其眾。能者，獸，形色似熊，足似鹿。爲物堅中而強力，人之有賢才者，皆謂之能也。"}]},{"id":"a58","section":"高祖本紀第八","anchor":"貴，且卜筮之，莫如劉季最吉。」於是劉季數讓。眾莫敢爲，乃立季爲沛公。","notes":[{"source":"集解","text":"徐廣曰：「九月也。」駰案：《漢書音義》曰「舊楚僭稱王，其縣宰爲公。陳涉爲楚王，沛公起應涉，故從楚制稱曰公」。"}]},{"id":"a59","section":"高祖本紀第八","anchor":"最吉。」於是劉季數讓。眾莫敢爲，乃立季爲沛公。祠黃帝，祭蚩尤於沛庭，","notes":[{"source":"集解","text":"應劭曰：「《左傳》曰黃帝戰於阪泉，以定天下。蚩尤好五兵，故祠祭之求福祥也。」瓚曰：「管仲云『割盧山交而出水，金從之出，蚩尤受之以作劍戟』。」"},{"source":"索隱","text":"按：管子云「葛盧之山，發而出金」，今注引「發」作「交」及「割」，皆誤也。"}]},{"id":"a60","section":"高祖本紀第八","anchor":"」於是劉季數讓。眾莫敢爲，乃立季爲沛公。祠黃帝，祭蚩尤於沛庭，而釁鼓","notes":[{"source":"集解","text":"應劭曰：「釁，祭也。殺牲以血塗鼓曰釁。」瓚曰：「案《禮記》及《大戴禮》有釁廟之禮，皆無祭事。」"},{"source":"索隱","text":"說文云：「釁，血祭也。」司馬法曰：「血于鼙鼓者，神戎器也。」顏師古曰：「凡殺牲以血祭者，皆名爲釁。」臣瓚以爲「皆無祭事」，非也。又古人新成鐘鼎，亦必釁之。應劭云：「釁呼爲舋。」馬融注《周禮》灼龜之兆云：「謂其象似玉、瓦、原之釁㙤，是用名之。」此說皆非。㙤音火稼反。"}]},{"id":"a61","section":"高祖本紀第八","anchor":"讓。眾莫敢爲，乃立季爲沛公。祠黃帝，祭蚩尤於沛庭，而釁鼓旗，幟皆赤。","notes":[{"source":"索隱","text":"墨翟云：「幟，帛長丈五，廣半幅。」字詁云：「幟，標也。」《字林》云：「熊旗五斿，謂與士卒爲期於其下，故曰旗也。」幟，或作「識」，或作「志」。嵇康音試。蕭該音熾。"}]},{"id":"a62","section":"高祖本紀第八","anchor":"，故上赤。於是少年豪吏如蕭、曹、樊噲等皆爲收沛子弟二三千人，攻胡陵、","notes":[{"source":"索隱","text":"鄧展曰：「縣名，屬山陽，章帝改曰胡陸。」"}]},{"id":"a63","section":"高祖本紀第八","anchor":"赤。於是少年豪吏如蕭、曹、樊噲等皆爲收沛子弟二三千人，攻胡陵、方與，","notes":[{"source":"集解","text":"鄭德曰：「音房豫，屬山陽郡。」"},{"source":"索隱","text":"鄭玄曰「屬山陽」也。"}]},{"id":"a64","section":"高祖本紀第八","anchor":"秦二世二年，陳涉之將周章","notes":[{"source":"索隱","text":"應劭云：「章字文，陳人。」"}]},{"id":"a65","section":"高祖本紀第八","anchor":"秦二世二年，陳涉之將周章軍西至戲","notes":[{"source":"索隱","text":"文穎云：「在新豐東二十里戲亭北。」孟康云：「水名也。」又述征記云：「戲水自驪山馮公谷北流，歷戲亭，東入渭。」按：今其水東惟有戲驛存。"}]},{"id":"a66","section":"高祖本紀第八","anchor":"秦二世二年，陳涉之將周章軍西至戲而還。","notes":[{"source":"索隱","text":"爲章邯所破而還。邯音酣。"}]},{"id":"a67","section":"高祖本紀第八","anchor":"秦二世二年，陳涉之將周章軍西至戲而還。燕、趙、齊、魏皆自立爲王。","notes":[{"source":"索隱","text":"按：《漢書》高紀，二世二年八月，武臣自立爲趙王，田儋自立爲齊王，韓廣自立爲燕王，魏咎自立爲魏王也。"}]},{"id":"a68","section":"高祖本紀第八","anchor":"之將周章軍西至戲而還。燕、趙、齊、魏皆自立爲王。項氏起吳。秦泗川監平","notes":[{"source":"集解","text":"文穎曰：「泗川，今沛郡也，高祖更名沛。秦時御史監郡，若今刺史。平，名也。」"},{"source":"索隱","text":"如淳云：「秦并天下爲三十六郡，置守、尉、監，故此有『監平』，下有『守壯』，則平、壯皆名也。」"}]},{"id":"a69","section":"高祖本紀第八","anchor":"泗川監平將兵圍豐，二日，出與戰，破之。命雍齒守豐，引兵之薛。泗州守壯","notes":[{"source":"集解","text":"如淳曰：「壯，名也。」"}]},{"id":"a70","section":"高祖本紀第八","anchor":"，二日，出與戰，破之。命雍齒守豐，引兵之薛。泗州守壯敗於薛，走至戚，","notes":[{"source":"集解","text":"如淳曰：「戚音將毒反。」"},{"source":"索隱","text":"晉灼云：「東海縣也。」鄭德、包愷並如字讀。李登音千笠反。"},{"source":"正義","text":"《括地志》云：「沂州臨沂縣有漢戚縣故城。《地理志》云臨沂縣屬東海郡。」"}]},{"id":"a71","section":"高祖本紀第八","anchor":"守豐，引兵之薛。泗州守壯敗於薛，走至戚，沛公左司馬得泗川守壯，殺之。","notes":[{"source":"索隱","text":"顏師古云「得，司馬之名」，非也。按：後云「左司馬曹無傷」，自此已下更不見替易處，蓋是左司馬無傷得泗川守壯而殺之耳。"}]},{"id":"a72","section":"高祖本紀第八","anchor":"。泗州守壯敗於薛，走至戚，沛公左司馬得泗川守壯，殺之。沛公還軍亢父，","notes":[{"source":"集解","text":"鄭德曰：「亢音人相亢答，父音甫。屬任城郡。」"},{"source":"索隱","text":"舊音剛。劉伯莊、包愷並同音苦浪反。"},{"source":"正義","text":"音剛，又苦浪反。《括地志》云：「亢父，縣也，沛公屯軍於此也。」"}]},{"id":"a73","section":"高祖本紀第八","anchor":"攻方與）未戰。陳王使魏人周市略地。周市使人謂雍齒曰：「豐，故梁徙也。","notes":[{"source":"集解","text":"文穎曰：「梁惠王孫假爲秦所滅，轉東徙於豐，故曰『豐，梁徙』。」"}]},{"id":"a74","section":"高祖本紀第八","anchor":"數十城。齒今下魏，魏以齒爲侯守豐。不下，且屠豐。」雍齒雅不欲屬沛公，","notes":[{"source":"集解","text":"服虔曰：「雅，故也。」蘇林曰：「雅，素也。」"}]},{"id":"a75","section":"高祖本紀第八","anchor":"豐，不能取。沛公病，還之沛。沛公怨雍齒與豐子弟叛之，聞東陽甯君、秦嘉","notes":[{"source":"集解","text":"文穎曰：「秦嘉，東陽郡人也，爲甯縣君。」瓚曰：「陳勝傳曰『廣陵人秦嘉』，然則嘉非東陽人也。秦嘉初起兵於郯，號曰大司馬，又不爲甯縣君。東陽甯君自一人，秦嘉又自一人。」"},{"source":"索隱","text":"臣瓚以爲二人。按：下文直云「東陽甯君」，又別言「秦嘉」，明臣瓚之說爲得。顏師古以甯是姓，君者，時人號曰君耳。"}]},{"id":"a76","section":"高祖本紀第八","anchor":"還之沛。沛公怨雍齒與豐子弟叛之，聞東陽甯君、秦嘉立景駒爲假王，在留，","notes":[{"source":"索隱","text":"韋昭云：「今彭城留縣也。」"},{"source":"正義","text":"《括地志》云：「留城在徐州沛縣東南五十里，即張良所封處。」"}]},{"id":"a77","section":"高祖本紀第八","anchor":"駒爲假王，在留，乃往從之，欲請兵以攻豐。是時秦將章邯從陳，別將司馬𡰥","notes":[{"source":"集解","text":"如淳曰：「從陳涉將也。涉在陳，其將相別在他許，皆稱陳。𡰥，章邯司馬。」"},{"source":"索隱","text":"謂章邯從陳別將，將兵向他處，而遣司馬𡰥將領兵士，北定楚地，故如淳云「𡰥，章邯司馬」也。孔文祥亦曰「邯別遣𡰥屠相」。又一說云「從謂追逐之，言章邯討逐陳別將，而司馬𡰥別將兵北定楚」，亦通。"}]},{"id":"a78","section":"高祖本紀第八","anchor":"欲請兵以攻豐。是時秦將章邯從陳，別將司馬𡰥將兵北定楚地，屠相，至碭。","notes":[{"source":"索隱","text":"韋昭云：「相，沛縣。」應劭曰：「碭屬梁國。」蘇林音唐，又音宕。"},{"source":"正義","text":"《括地志》云：「故相城在徐州符離縣西北九十里。碭在宋州東一百五十里。」"}]},{"id":"a79","section":"高祖本紀第八","anchor":"別將司馬𡰥將兵北定楚地，屠相，至碭。東陽甯君、沛公引兵西，與戰蕭西，","notes":[{"source":"索隱","text":"韋昭云：「蕭，沛之縣名，謂在蕭縣之西也。」"}]},{"id":"a80","section":"高祖本紀第八","anchor":"利。還收兵聚留，引兵攻碭，三日乃取碭。因收碭兵，得五六千人。攻下邑，","notes":[{"source":"索隱","text":"韋昭云：「縣名，屬梁國。」"}]},{"id":"a81","section":"高祖本紀第八","anchor":"收兵聚留，引兵攻碭，三日乃取碭。因收碭兵，得五六千人。攻下邑，拔之。","notes":[{"source":"索隱","text":"按：范曄云「得城爲拔」是也。"}]},{"id":"a82","section":"高祖本紀第八","anchor":"三日乃取碭。因收碭兵，得五六千人。攻下邑，拔之。還軍豐。聞項梁在薛，","notes":[{"source":"正義","text":"今徐州滕縣，故薛城也。"}]},{"id":"a83","section":"高祖本紀第八","anchor":"碭兵，得五六千人。攻下邑，拔之。還軍豐。聞項梁在薛，從騎百餘往見之。","notes":[{"source":"集解","text":"徐廣曰：「三月。」"}]},{"id":"a84","section":"高祖本紀第八","anchor":"軍豐。聞項梁在薛，從騎百餘往見之。項梁益沛公卒五千人，五大夫將十人。","notes":[{"source":"集解","text":"蘇林曰：「五大夫，第九爵也。以五大夫爲將，凡十人也。」"}]},{"id":"a85","section":"高祖本紀第八","anchor":"從騎百餘往見之。項梁益沛公卒五千人，五大夫將十人。沛公還，引兵攻豐。","notes":[{"source":"集解","text":"徐廣曰：「表云『拔之，雍齒奔魏』。」"}]},{"id":"a86","section":"高祖本紀第八","anchor":"從項梁月餘，項羽已拔襄城","notes":[{"source":"索隱","text":"韋昭云：「穎川縣。」"},{"source":"正義","text":"襄城，許州縣。"}]},{"id":"a87","section":"高祖本紀第八","anchor":"城還。項梁盡召別將居薛。聞陳王定死，因立楚後懷王孫心爲楚王，治盱台。","notes":[{"source":"索隱","text":"韋昭云：「臨淮縣。音吁夷。」"},{"source":"正義","text":"楚縣也。"}]},{"id":"a88","section":"高祖本紀第八","anchor":"楚後懷王孫心爲楚王，治盱台。項梁號武信君。居數月，北攻亢父，救東阿，","notes":[{"source":"索隱","text":"韋昭云：「東郡之縣名。」"},{"source":"正義","text":"濟州縣也。"}]},{"id":"a89","section":"高祖本紀第八","anchor":"。項梁號武信君。居數月，北攻亢父，救東阿，破秦軍。齊軍歸，楚獨追北，","notes":[{"source":"集解","text":"服虔曰：「師敗曰北。」"}]},{"id":"a90","section":"高祖本紀第八","anchor":"，北攻亢父，救東阿，破秦軍。齊軍歸，楚獨追北，使沛公、項羽別攻城陽，","notes":[{"source":"索隱","text":"按《地理志》屬濟陰。"}]},{"id":"a91","section":"高祖本紀第八","anchor":"，破秦軍。齊軍歸，楚獨追北，使沛公、項羽別攻城陽，屠之。軍濮陽之東，","notes":[{"source":"索隱","text":"韋昭云：「東郡之縣名。」"},{"source":"正義","text":"濮陽故城在濮州西八十六里，本漢濮陽縣。"}]},{"id":"a92","section":"高祖本紀第八","anchor":"秦軍復振，","notes":[{"source":"集解","text":"李奇曰：「振，整也。」如淳曰：「振，起也。收敗卒自振迅而復起也。」"}]},{"id":"a93","section":"高祖本紀第八","anchor":"秦軍復振，守濮陽，環水。","notes":[{"source":"集解","text":"文穎曰：「決水以自環守爲固也。」張晏曰：「依河水以自環繞作壘。」"},{"source":"正義","text":"按：二說皆通。其濮陽縣北臨黃河，言秦軍北阻黃河，南鑿溝引黃河水環繞作壁壘爲固，楚軍乃去。"}]},{"id":"a94","section":"高祖本紀第八","anchor":"秦軍復振，守濮陽，環水。楚軍去而攻定陶，","notes":[{"source":"索隱","text":"按：《地理志》濟陰之縣也。"}]},{"id":"a95","section":"高祖本紀第八","anchor":"守濮陽，環水。楚軍去而攻定陶，定陶未下。沛公與項羽西略地至雍丘之下，","notes":[{"source":"索隱","text":"韋昭云：「故杞國，今陳留之縣。」"}]},{"id":"a96","section":"高祖本紀第八","anchor":"下。沛公與項羽西略地至雍丘之下，與秦軍戰，大破之，斬李由。還攻外黃，","notes":[{"source":"索隱","text":"韋昭云：「上陳留縣。」"},{"source":"正義","text":"在雍丘東。"}]},{"id":"a97","section":"高祖本紀第八","anchor":"項梁再破秦軍，有驕色。宋義","notes":[{"source":"索隱","text":"荀悅漢紀云「故楚令尹宋義」，當別有所出也。"}]},{"id":"a98","section":"高祖本紀第八","anchor":"項梁再破秦軍，有驕色。宋義諫，不聽。秦益章邯兵，夜銜枚擊項梁，","notes":[{"source":"集解","text":"《周禮》有銜枚氏。鄭玄曰「銜枚，止言語囂讙也。枚狀如箸，橫銜之，繣結於項者」。繣音獲。"}]},{"id":"a99","section":"高祖本紀第八","anchor":"破項梁軍，則以爲楚地兵不足憂，乃渡河，北擊趙，大破之。當是之時，趙歇","notes":[{"source":"索隱","text":"蘇林音如字。鄭德音「遏絕」之「遏」。徐廣音烏轄反。今依字讀之也。"}]},{"id":"a100","section":"高祖本紀第八","anchor":"見項梁軍破，恐，徙盱台都彭城，并呂臣、項羽軍自將之。以沛公爲碭郡長，","notes":[{"source":"正義","text":"《括地志》云：「宋州本秦碭郡。」蘇林云：「長如郡守。」韋昭云：「秦名曰守，是時改曰長。」"}]},{"id":"a101","section":"高祖本紀第八","anchor":"侯，將碭郡兵。封項羽爲長安侯，號爲魯公。呂臣爲司徒，其父呂青爲令尹。","notes":[{"source":"索隱","text":"按表，青封信陽侯。"},{"source":"正義","text":"應劭云：「天子曰師尹，諸侯曰令尹。時去六國近，故置令尹。」臣瓚曰：「諸侯之卿，唯楚稱令尹，其餘國不稱。時立楚之後，故置官司皆如楚舊也。」"}]},{"id":"a102","section":"高祖本紀第八","anchor":"，范增爲末將，北救趙。令沛公西略地入關。與諸將約，先入定關中者王之。","notes":[{"source":"索隱","text":"韋昭云：「函谷、武關也。」又三輔舊事云：「西以散關爲界，東以函谷爲界，二關之中謂之關中。」"}]},{"id":"a103","section":"高祖本紀第八","anchor":"當是時，秦兵彊，常乘勝逐北，諸將莫利先入關。獨項羽怨秦破項梁軍，奮，","notes":[{"source":"索隱","text":"韋昭云：「憤激也。」"}]},{"id":"a104","section":"高祖本紀第八","anchor":"秦破項梁軍，奮，願與沛公西入關。懷王諸老將皆曰：「項羽爲人僄悍猾賊。","notes":[{"source":"索隱","text":"說文云：「僄，疾也；悍，勇也。」方言云：「僄，輕也。」劉音匹妙反。猾賊，《漢書》作「禍賊」也。"}]},{"id":"a105","section":"高祖本紀第八","anchor":"入關。懷王諸老將皆曰：「項羽爲人僄悍猾賊。項羽嘗攻襄城，襄城無遺類，","notes":[{"source":"集解","text":"徐廣曰：「遺，一作『噍』。噍，食也，音在妙反。」駰案：如淳曰「類無復有活而噍食者也。青州俗言無　遺爲無噍類」。"}]},{"id":"a106","section":"高祖本紀第八","anchor":"猾賊。項羽嘗攻襄城，襄城無遺類，皆阬之，諸所過無不殘滅。且楚數進取，","notes":[{"source":"集解","text":"如淳曰：「楚謂陳涉也。數進取，多所攻取。」"}]},{"id":"a107","section":"高祖本紀第八","anchor":"羽嘗攻襄城，襄城無遺類，皆阬之，諸所過無不殘滅。且楚數進取，前陳王、","notes":[{"source":"集解","text":"《漢書音義》曰：「陳涉也。」"}]},{"id":"a108","section":"高祖本紀第八","anchor":"諸所過無不殘滅。且楚數進取，前陳王、項梁皆敗。不如更遣長者扶義而西，","notes":[{"source":"正義","text":"遣長者扶持仁義而西，告諭秦長少，令降下也。"}]},{"id":"a109","section":"高祖本紀第八","anchor":"父兄。秦父兄苦其主久矣，今誠得長者往，毋侵暴，宜可下。今項羽僄悍，今","notes":[{"source":"集解","text":"徐廣曰：「一無此字。」"}]},{"id":"a110","section":"高祖本紀第八","anchor":"大長者，可遣。」卒不許項羽，而遣沛公西略地，收陳王、項梁散卒。乃道碭","notes":[{"source":"集解","text":"《漢書音義》曰：「道由碭也。」"}]},{"id":"a111","section":"高祖本紀第八","anchor":"」卒不許項羽，而遣沛公西略地，收陳王、項梁散卒。乃道碭至成陽，與杠里","notes":[{"source":"集解","text":"《漢書音義》曰：「二縣名。」"},{"source":"索隱","text":"成陽在濟陰，韋昭云「在穎川」，非也。服虔云：「杠里，縣名。」如淳云：「秦軍所別屯地名也。」"}]},{"id":"a112","section":"高祖本紀第八","anchor":"至成陽，與杠里秦軍夾壁，破（魏）〔秦〕二軍。楚軍出兵擊王離，大破之。","notes":[{"source":"集解","text":"徐廣曰：「表云三年十月，攻破東郡尉及王離軍於成武南。」"}]},{"id":"a113","section":"高祖本紀第八","anchor":"沛公引兵西，遇彭越昌邑，","notes":[{"source":"正義","text":"《地理志》云昌邑縣屬山陽。《括地志》云：「在曹州成武縣東北三十二里，有梁丘故城是也。」"}]},{"id":"a114","section":"高祖本紀第八","anchor":"沛公引兵西，遇彭越昌邑，因與俱攻秦軍，戰不利。還至栗，","notes":[{"source":"索隱","text":"韋昭云：「縣名，屬沛。」"}]},{"id":"a115","section":"高祖本紀第八","anchor":"沛公引兵西，遇彭越昌邑，因與俱攻秦軍，戰不利。還至栗，遇剛武侯，","notes":[{"source":"集解","text":"應劭曰：「楚懷王將也。」《漢書音義》曰：「《功臣表》云棘蒲剛侯陳武。武，一姓柴。『剛武侯』宜爲『剛侯武』，魏將也。」瓚曰：「《功臣表》柴武以將軍起薛，別救東阿，至霸上，入漢中，非懷王將也，又非魏將也，例未稱謚。」"},{"source":"正義","text":"顏師古云：「史失其名姓，唯識其爵號，不知誰也，不當改爲『剛侯武』。應氏以爲懷王將，又云魏將，無據矣。」表六年三月封。孟、顏二人說是。"}]},{"id":"a116","section":"高祖本紀第八","anchor":"至栗，遇剛武侯，奪其軍，可四千餘人，并之。與魏將皇欣、魏申徒武蒲之軍","notes":[{"source":"正義","text":"並魏將也。欣字或作「訢」，音許斤反。蒲，《漢書》作「滿」，並通也。"}]},{"id":"a117","section":"高祖本紀第八","anchor":"餘人，并之。與魏將皇欣、魏申徒武蒲之軍并攻昌邑，昌邑未拔。西過高陽。","notes":[{"source":"集解","text":"文穎曰：「聚邑名也，屬陳留圉縣。」瓚曰：「陳留傳曰在雍丘西南。」"}]},{"id":"a118","section":"高祖本紀第八","anchor":"并之。與魏將皇欣、魏申徒武蒲之軍并攻昌邑，昌邑未拔。西過高陽。酈食其","notes":[{"source":"集解","text":"鄭德曰：「音歷異基。」"}]},{"id":"a119","section":"高祖本紀第八","anchor":"秦，不宜踞見長者。」於是沛公起，攝衣謝之，延上坐。食其說沛公襲陳留，","notes":[{"source":"集解","text":"《漢書音義》曰：「《春秋傳》曰輕行無鐘鼓曰襲。」"}]},{"id":"a120","section":"高祖本紀第八","anchor":"，攝衣謝之，延上坐。食其說沛公襲陳留，得秦積粟。乃以酈食其爲廣野君，","notes":[{"source":"索隱","text":"韋昭云：「在山陽。」"}]},{"id":"a121","section":"高祖本紀第八","anchor":"陳留，得秦積粟。乃以酈食其爲廣野君，酈商爲將，將陳留兵，與偕攻開封，","notes":[{"source":"索隱","text":"韋昭云：「河南縣。」"}]},{"id":"a122","section":"高祖本紀第八","anchor":"野君，酈商爲將，將陳留兵，與偕攻開封，開封未拔。西與秦將楊熊戰白馬，","notes":[{"source":"索隱","text":"韋昭云：「東郡縣。」"},{"source":"正義","text":"《括地志》云：「白馬故城在滑州衞南縣西南二十四里。戴延之《西征記》云白馬城，故衞之漕邑。」"}]},{"id":"a123","section":"高祖本紀第八","anchor":"商爲將，將陳留兵，與偕攻開封，開封未拔。西與秦將楊熊戰白馬，又戰曲遇","notes":[{"source":"索隱","text":"徐廣云「在中牟」。韋昭云「志不載」。司馬彪郡國志中牟有曲遇聚也。"}]},{"id":"a124","section":"高祖本紀第八","anchor":"封，開封未拔。西與秦將楊熊戰白馬，又戰曲遇東，大破之。楊熊走之滎陽，","notes":[{"source":"索隱","text":"韋昭云：「故衞地，河南縣也。」"}]},{"id":"a125","section":"高祖本紀第八","anchor":"秦將楊熊戰白馬，又戰曲遇東，大破之。楊熊走之滎陽，二世使使者斬以徇。","notes":[{"source":"集解","text":"徐廣曰：「四月。」"}]},{"id":"a126","section":"高祖本紀第八","anchor":"楊熊走之滎陽，二世使使者斬以徇。南攻潁陽，屠之。因張良遂略韓地轘轅。","notes":[{"source":"集解","text":"文穎曰：「河南新鄭南至潁川南北，皆韓地也。以良累世相韓，故因之。」瓚曰：「轘轅，險道名，在緱氏東南。」"},{"source":"索隱","text":"按：《十三州志》云河南緱氏縣，以山爲名。一云轘轅凡九十二曲，是險道也。"}]},{"id":"a127","section":"高祖本紀第八","anchor":"當是時，趙別將司馬卬方欲渡河入關，沛公乃北攻平陰，","notes":[{"source":"集解","text":"《地理志》河南有平陰縣，今河陰是也。"}]},{"id":"a128","section":"高祖本紀第八","anchor":"欲渡河入關，沛公乃北攻平陰，絕河津。南，戰雒陽東，軍不利，還至陽城，","notes":[{"source":"正義","text":"今洛州，夏禹所都。"}]},{"id":"a129","section":"高祖本紀第八","anchor":"平陰，絕河津。南，戰雒陽東，軍不利，還至陽城，收軍中馬騎，與南陽守齮","notes":[{"source":"索隱","text":"音檥。許慎以爲側齧也。"}]},{"id":"a130","section":"高祖本紀第八","anchor":"河津。南，戰雒陽東，軍不利，還至陽城，收軍中馬騎，與南陽守齮戰犨東，","notes":[{"source":"集解","text":"《地理志》南陽有犨縣。"}]},{"id":"a131","section":"高祖本紀第八","anchor":"收軍中馬騎，與南陽守齮戰犨東，破之。略南陽郡，南陽守齮走，保城守宛。","notes":[{"source":"正義","text":"守音狩。宛，於元反。《括地志》云：「南陽縣故城在宛大城之南隅，其西南有二面，皆故宛城。」"}]},{"id":"a132","section":"高祖本紀第八","anchor":"後擊，彊秦在前，此危道也。」於是沛公乃夜引兵從他道還，更旗幟，黎明，","notes":[{"source":"索隱","text":"音犂。黎猶比也，謂比至天明也。《漢書》作「遲」，音值。值，待也，謂待天明，皆言早意也。"}]},{"id":"a133","section":"高祖本紀第八","anchor":"前，此危道也。」於是沛公乃夜引兵從他道還，更旗幟，黎明，圍宛城三帀。","notes":[{"source":"索隱","text":"按：《楚漢春秋》曰「上南攻宛，匿旌旗，人銜枚，馬東舌，雞未鳴，圍宛城三帀」也。"}]},{"id":"a134","section":"高祖本紀第八","anchor":"郡之都也，連城數十，人民眾，積蓄多，吏人自以爲降必死，故皆堅守乘城。","notes":[{"source":"索隱","text":"李奇曰：「乘，守也。」韋昭曰：「乘，登也。」"}]},{"id":"a135","section":"高祖本紀第八","anchor":"之西。諸城未下者，聞聲爭開門而待，足下通行無所累。」沛公曰：「善。」","notes":[{"source":"集解","text":"徐廣曰：「七月也。」"}]},{"id":"a136","section":"高祖本紀第八","anchor":"，聞聲爭開門而待，足下通行無所累。」沛公曰：「善。」乃以宛守爲殷侯，","notes":[{"source":"索隱","text":"韋昭曰：「在河內。」"}]},{"id":"a137","section":"高祖本紀第八","anchor":"公曰：「善。」乃以宛守爲殷侯，封陳恢千戶。引兵西，無不下者。至丹水，","notes":[{"source":"索隱","text":"韋昭曰：「在河內。」"},{"source":"正義","text":"《括地志》云：「故丹城在鄧州內鄉縣西南百三十里，南去丹水二百步。汲冢紀年云后稷放帝子丹朱于丹水是也。《輿地志》云秦爲丹水縣也。《地理志》云丹水縣屬弘農郡。抱朴子云『丹水出丹魚，先夏至十日，夜伺之，魚浮水側，光照如火，網而取之，割其血以塗足，可以步行水上，長居川中不溺』。」"}]},{"id":"a138","section":"高祖本紀第八","anchor":"。」乃以宛守爲殷侯，封陳恢千戶。引兵西，無不下者。至丹水，高武侯鰓、","notes":[{"source":"集解","text":"蘇林曰：「鰓音『魚鰓』之『鰓』。」晉灼曰：「《功臣表》戚鰓也。」"}]},{"id":"a139","section":"高祖本紀第八","anchor":"侯，封陳恢千戶。引兵西，無不下者。至丹水，高武侯鰓、襄侯王陵降西陵。","notes":[{"source":"集解","text":"韋昭曰：「漢封王陵爲安國侯，初起兵時在南陽，南陽有穰縣，疑『襄』當爲『穰』，而無『禾』，字省耳。今『邵公』或作『召』字，此類多矣。」瓚曰：「時韓成封穰侯，江夏有襄，是陵所封。」"},{"source":"索隱","text":"按：王陵封安國侯，是定天下爲丞相時封耳。此言襄侯，當如臣瓚解，蓋初封江夏之襄也。"}]},{"id":"a140","section":"高祖本紀第八","anchor":"千戶。引兵西，無不下者。至丹水，高武侯鰓、襄侯王陵降西陵。還攻胡陽，","notes":[{"source":"集解","text":"一云「陵」。"},{"source":"索隱","text":"韋昭曰：「南陽縣。」"}]},{"id":"a141","section":"高祖本紀第八","anchor":"高武侯鰓、襄侯王陵降西陵。還攻胡陽，遇番君別將梅鋗，與皆，降析、酈。","notes":[{"source":"集解","text":"如淳曰：「持益反。」"},{"source":"索隱","text":"鄒誕生音錫。酈音歷，蘇林、如淳音擲。析屬弘農，酈屬南陽，出《地理志》。而《左傳》云析一名白羽。顏師古云「析，今內鄉縣。酈，今菊潭縣」。"}]},{"id":"a142","section":"高祖本紀第八","anchor":"。沛公以爲詐，乃用張良計，使酈生、陸賈往說秦將，啗以利，因襲攻武關，","notes":[{"source":"索隱","text":"《左傳》云楚司馬起（營所）〔豐析〕以臨上雒，謂晉人曰「將通於少習」，杜預以爲商縣武關也。又太康《地理志》武關當冠軍縣西，嶢關在武關西也。"}]},{"id":"a143","section":"高祖本紀第八","anchor":"因襲攻武關，破之。又與秦軍戰於藍田南，益張疑兵旗幟，諸所過毋得掠鹵，","notes":[{"source":"集解","text":"應劭曰：「鹵與『虜』同。」"}]},{"id":"a144","section":"元年","anchor":"漢元年十月，","notes":[{"source":"集解","text":"如淳曰：「張蒼傳云以高祖十月至霸上，故因秦以十月爲歲首。」"},{"source":"正義","text":"沛公乙未年十月至霸上。項羽封十八諸侯，沛公封漢王，後劉項五年戰鬬，漢遂滅楚，天下歸漢，故卻書初至霸上之月。"}]},{"id":"a145","section":"元年","anchor":"漢元年十月，沛公兵遂先諸侯至霸上。","notes":[{"source":"正義","text":"故霸陵在雍州萬年縣東北二十五里。漢霸陵，文帝之陵邑也，東南去霸陵十里。《地理志》云：「霸陵故芷陽，文帝更名。」三秦記云：「霸城，秦穆公築爲宮，因名霸城。漢於此置霸陵。」廟記云：「霸城，漢文帝築。沛公入關，遂至霸上，即此也。」"}]},{"id":"a146","section":"元年","anchor":"月，沛公兵遂先諸侯至霸上。秦王子嬰素車白馬，係頸以組，封皇帝璽符節，","notes":[{"source":"索隱","text":"韋昭云：「天子印稱璽，又獨以玉。符，發兵符也。節，使者所擁也。」說文云：「符，信也。漢制以竹，長六寸，分而相合。」釋名云：「節爲號令賞罰之節也。又節毛上下相重，取象竹節。」又漢官儀云：「子嬰上始皇璽，因服御之，代代傳受，號曰『漢傳國璽』也。」"},{"source":"正義","text":"按：天子有六璽，皇帝行璽、皇帝之璽、皇帝信璽、天子行璽、天子之璽、天子信璽。皇帝信璽凡事皆用之，璽令施行；天子信璽以遷拜封王侯；天子之璽以發兵。皆以武都紫泥封，青囊白素裏，兩端無縫。三秦記云紫泥水在今成州。《輿地志》云漢封詔璽用紫泥，則此水之泥也。"}]},{"id":"a147","section":"元年","anchor":"遂先諸侯至霸上。秦王子嬰素車白馬，係頸以組，封皇帝璽符節，降軹道旁。","notes":[{"source":"索隱","text":"枳音只。漢宮殿疏云枳道亭東去霸城觀四里，觀東去霸水百步。蘇林云在長安東十三里也。"},{"source":"正義","text":"軹音紙。《括地志》云：「軹道在雍州萬年縣東北十六里苑中。」"}]},{"id":"a148","section":"元年","anchor":"秦王子嬰素車白馬，係頸以組，封皇帝璽符節，降軹道旁。諸將或言誅秦王。","notes":[{"source":"索隱","text":"《楚漢春秋》曰：「樊噲請殺之。」"}]},{"id":"a149","section":"元年","anchor":"「始懷王遣我，固以能寬容；且人已服降，又殺之，不祥。」乃以秦王屬吏，","notes":[{"source":"正義","text":"屬，之欲反。屬，付也。"}]},{"id":"a150","section":"元年","anchor":"；且人已服降，又殺之，不祥。」乃以秦王屬吏，遂西入咸陽。欲止宮休舍，","notes":[{"source":"正義","text":"休，息也。言欲居止宮殿中而息也。"}]},{"id":"a151","section":"元年","anchor":"秦重寶財物府庫，還軍霸上。召諸縣父老豪桀曰：「父老苦秦苛法久矣，誹謗","notes":[{"source":"索隱","text":"劉伯莊、樂彥同音方未反。"}]},{"id":"a152","section":"元年","anchor":"軍霸上。召諸縣父老豪桀曰：「父老苦秦苛法久矣，誹謗者族，偶語者弃市。","notes":[{"source":"集解","text":"應劭曰：「秦禁民聚語。偶，對也。」瓚曰：「始皇本紀曰『偶語經書者弃市』。」"},{"source":"索隱","text":"按：《禮》云「刑人於市，與眾鼂之」，故今律謂絞刑爲「弃市」是也。"}]},{"id":"a153","section":"元年","anchor":"語者弃市。吾與諸侯約，先入關者王之，吾當王關中。與父老約，法三章耳：","notes":[{"source":"索隱","text":"殺人，傷人及盜。"}]},{"id":"a154","section":"元年","anchor":"入關者王之，吾當王關中。與父老約，法三章耳：殺人者死，傷人及盜抵罪。","notes":[{"source":"集解","text":"應劭曰：「抵，至也，又當也。除秦酷政，但至於罪也。」李斐曰：「傷人有曲直，盜臧有多少，罪名不可豫定，故凡言抵罪，未知抵何罪也。」張晏曰：「秦法，一人犯罪，舉家及鄰伍坐之，今但當其身坐，合於康誥『父子兄弟罪不相及』也。」"},{"source":"索隱","text":"韋昭云：「抵，當也。謂使各當其罪。」今按：秦法有三族之刑，漢但約法三章耳，殺人者死，傷人及盜者使之抵罪，餘並不論其辜，以言省刑也。則抵訓爲至，殺人以外，唯傷人及盜使至罪名耳。"}]},{"id":"a155","section":"元年","anchor":"，法三章耳：殺人者死，傷人及盜抵罪。餘悉除去秦法。諸吏人皆案堵如故。","notes":[{"source":"集解","text":"應劭曰：「案，案次第；堵，牆堵也。」"}]},{"id":"a156","section":"元年","anchor":"或說沛公","notes":[{"source":"索隱","text":"按：《楚漢春秋》云解先生云「遣守函谷，無內項王」，而張良系家云「鯫生說我」，則鯫生是小生，即解生。"}]},{"id":"a157","section":"元年","anchor":"，項羽乃號爲雍王，王關中。今則來，沛公恐不得有此。可急使兵守函谷關，","notes":[{"source":"正義","text":"顏師古曰：「今桃林南有洪溜澗，古函谷也。其水北流入河，西岸猶有舊關餘跡」。《西征記》云：「道形如函也。其水山原壁立數十仞，谷中容一車。」"}]},{"id":"a158","section":"元年","anchor":"關門閉。聞沛公已定關中，大怒，使黥布等攻破函谷關。十二月中，遂至戲。","notes":[{"source":"正義","text":"許宜反。"}]},{"id":"a159","section":"元年","anchor":"，使人言項羽曰：「沛公欲王關中，令子嬰爲相，珍寶盡有之。」欲以求封。","notes":[{"source":"正義","text":"曹無傷欲就項羽求封。"}]},{"id":"a160","section":"元年","anchor":"沛公欲王關中，令子嬰爲相，珍寶盡有之。」欲以求封。亞父勸項羽擊沛公。","notes":[{"source":"索隱","text":"范增也。項羽得范增，號曰亞父，言尊之亞於父。猶管仲，齊謂仲父。父並音甫也。"}]},{"id":"a161","section":"元年","anchor":"公兵十萬，號二十萬，力不敵。會項伯欲活張良，夜往見良，因以文諭項羽，","notes":[{"source":"正義","text":"項羽本紀云項伯曰「沛父不先破關中，公豈敢入乎？今人有大功，擊之不義」。此以文諭之。"}]},{"id":"a162","section":"元年","anchor":"欲活張良，夜往見良，因以文諭項羽，項羽乃止。沛公從百餘騎，驅之鴻門，","notes":[{"source":"索隱","text":"按：姚察云在新豐古城東，未至戲水，道南有斷原、南北洞門是也。"}]},{"id":"a163","section":"元年","anchor":"王曰：「如約。」項羽怨懷王不肯令與沛公俱西入關，而北救趙，後天下約。","notes":[{"source":"正義","text":"懷王初約先入咸陽者王之，令羽北救趙，故失約在後也。"}]},{"id":"a164","section":"元年","anchor":"正月，","notes":[{"source":"正義","text":"崔浩云：「史官以正月紀四時，故書正月也。」荀悅云：「先春後正月也。」顏師古云：「凡此諸月號，皆太初正曆之後記事者追改之，非當時本稱也。以十月爲歲首，即以十月爲正月。今此正月，當時謂之四月也。他皆放此。」"}]},{"id":"a165","section":"元年","anchor":"，項羽自立爲西楚霸王，王梁、楚地九郡，都彭城。負約，更立沛公爲漢王，","notes":[{"source":"正義","text":"梁州本漢中郡，以漢水爲名。"}]},{"id":"a166","section":"元年","anchor":"霸王，王梁、楚地九郡，都彭城。負約，更立沛公爲漢王，王巴、蜀、漢中，","notes":[{"source":"集解","text":"徐廣曰：「三十二縣。」"}]},{"id":"a167","section":"元年","anchor":"沛公爲漢王，王巴、蜀、漢中，都南鄭。三分關中，立秦三將：章邯爲雍王，","notes":[{"source":"正義","text":"以岐州雍縣爲名。"}]},{"id":"a168","section":"元年","anchor":"漢中，都南鄭。三分關中，立秦三將：章邯爲雍王，都廢丘；司馬欣爲塞王，","notes":[{"source":"正義","text":"塞，先代反。韋昭云：「在長安東，名桃林塞。」按：桃林塞今華州潼關也。顏師古云「取河華之固爲阨塞耳，非桃林」。"}]},{"id":"a169","section":"元年","anchor":"南鄭。三分關中，立秦三將：章邯爲雍王，都廢丘；司馬欣爲塞王，都櫟陽；","notes":[{"source":"索隱","text":"因葬太上皇，改曰萬年。"}]},{"id":"a170","section":"元年","anchor":"中，立秦三將：章邯爲雍王，都廢丘；司馬欣爲塞王，都櫟陽；董翳爲翟王，","notes":[{"source":"正義","text":"文穎云：「本上郡，秦所置，項羽以蕫翳爲王，更名曰翟也。」"}]},{"id":"a171","section":"元年","anchor":"丘；司馬欣爲塞王，都櫟陽；董翳爲翟王，都高奴。楚將瑕丘申陽爲河南王，","notes":[{"source":"正義","text":"在黃河之南，故曰河南，即今河南府。"}]},{"id":"a172","section":"元年","anchor":"董翳爲翟王，都高奴。楚將瑕丘申陽爲河南王，都洛陽。趙將司馬卬爲殷王，","notes":[{"source":"正義","text":"以商帝盤庚國殷中之地，改商爲殷，在相州安陽縣，即北蒙殷墟，南去朝歌百三十六里，故號殷王，都朝歌。"}]},{"id":"a173","section":"元年","anchor":"將司馬卬爲殷王，都朝歌。趙王歇徙王代。趙相張耳爲常山王，都襄國。當陽","notes":[{"source":"索隱","text":"韋昭云：「南郡縣名。」"}]},{"id":"a174","section":"元年","anchor":"。趙王歇徙王代。趙相張耳爲常山王，都襄國。當陽君黥布爲九江王，都六。","notes":[{"source":"索隱","text":"《地理志》云六縣屬六安國。"}]},{"id":"a175","section":"元年","anchor":"耳爲常山王，都襄國。當陽君黥布爲九江王，都六。懷王柱國共敖爲臨江王，","notes":[{"source":"正義","text":"孟康云「本南郡，改爲臨江國」是也。"}]},{"id":"a176","section":"元年","anchor":"九江王，都六。懷王柱國共敖爲臨江王，都江陵。番君吳芮爲衡山王，都邾。","notes":[{"source":"索隱","text":"太康《地理志》云：「楚滅邾，遷其人於江南，因名縣也。」"}]},{"id":"a177","section":"元年","anchor":"四月，兵罷戲下，","notes":[{"source":"正義","text":"戲音麾：許慎注《淮南子》云：「戲，大旗也。」"}]},{"id":"a178","section":"元年","anchor":"侯各就國。漢王之國，項王使卒三萬人從，楚與諸侯之慕從者數萬人，從杜南","notes":[{"source":"正義","text":"韋昭云：「杜，今陵邑。」《括地志》云：「杜陵故城在雍州萬年縣東南十五里。漢杜陵縣，宣帝陵邑也，北去宣帝陵五里。廟記云故杜伯國。」"}]},{"id":"a179","section":"元年","anchor":"。漢王之國，項王使卒三萬人從，楚與諸侯之慕從者數萬人，從杜南入蝕中。","notes":[{"source":"集解","text":"李奇曰：「蝕音力，在杜南。」如淳曰：「蝕，入漢中道川谷名。」"},{"source":"索隱","text":"李奇音力，孟康音食。王劭按：說文作「𨪊」，器名也。地形似器，故名之。音力也。"}]},{"id":"a180","section":"元年","anchor":"王使卒三萬人從，楚與諸侯之慕從者數萬人，從杜南入蝕中。去輒燒絕棧道，","notes":[{"source":"索隱","text":"按系家，是用張良計也。棧道，閣道也。音士諫反。包愷音士版反。崔浩云：「險絕之處，傍鑿山巖，而施版梁爲閣。」"}]},{"id":"a181","section":"元年","anchor":"羽無東意。至南鄭，諸將及士卒多道亡歸，士卒皆歌思東歸。韓信說漢王曰：","notes":[{"source":"集解","text":"徐廣曰：「韓王信，非淮陰侯信也。」"}]},{"id":"a182","section":"元年","anchor":"歌思東歸。韓信說漢王曰：「項羽王諸將之有功者，而王獨居南鄭，是遷也。","notes":[{"source":"集解","text":"韋昭曰：「若有罪見遷徙。」"}]},{"id":"a183","section":"元年","anchor":"之有功者，而王獨居南鄭，是遷也。軍吏士卒皆山東之人也，日夜跂而望歸，","notes":[{"source":"正義","text":"跂音丘賜反。說文云：「跂，舉踵也。」司馬彪云：「跂，望也。」"}]},{"id":"a184","section":"元年","anchor":"項羽出關，使人徙義帝。曰：「古之帝者地方千里，必居上游。」","notes":[{"source":"正義","text":"音流。"}]},{"id":"a185","section":"元年","anchor":"曰：「古之帝者地方千里，必居上游。」乃使使徙義帝長沙郴縣，趣義帝行，","notes":[{"source":"正義","text":"趣音促。"}]},{"id":"a186","section":"元年","anchor":"反梁地。楚令蕭公角擊彭越，彭越大破之。陳餘怨項羽之弗王己也，令夏說說","notes":[{"source":"正義","text":"上音悅，下音稅。"}]},{"id":"a187","section":"元年","anchor":"八月，漢王用韓信之計，從故道","notes":[{"source":"集解","text":"《地理志》武都有故道縣。"}]},{"id":"a188","section":"元年","anchor":"八月，漢王用韓信之計，從故道還，襲雍王章邯。邯迎擊漢陳倉，","notes":[{"source":"正義","text":"今岐州縣也。"}]},{"id":"a189","section":"元年","anchor":"信之計，從故道還，襲雍王章邯。邯迎擊漢陳倉，雍兵敗，還走；止戰好畤，","notes":[{"source":"集解","text":"孟康曰：「畤音止，神靈之所在也，縣名，屬右扶風。」"}]},{"id":"a190","section":"元年","anchor":"；止戰好畤，又復敗，走廢丘。漢王遂定雍地。東至咸陽，引兵圍雍王廢丘，","notes":[{"source":"索隱","text":"按荀悅漢紀，令樊噲圍之。"}]},{"id":"a191","section":"元年","anchor":"東至咸陽，引兵圍雍王廢丘，而遣諸將略定隴西、北地、上郡。令將軍薛歐、","notes":[{"source":"集解","text":"音惡后反。"},{"source":"索隱","text":"按表，歐以舍人從，爲將軍，封廣平侯也。"}]},{"id":"a192","section":"元年","anchor":"咸陽，引兵圍雍王廢丘，而遣諸將略定隴西、北地、上郡。令將軍薛歐、王吸","notes":[{"source":"索隱","text":"按表，吸以中涓從，爲將軍，封清陽侯。"}]},{"id":"a193","section":"元年","anchor":"而遣諸將略定隴西、北地、上郡。令將軍薛歐、王吸出武關，因王陵兵南陽，","notes":[{"source":"集解","text":"如淳曰：「王陵亦聚黨數千人，居南陽。」"},{"source":"正義","text":"《括地志》云：「王陵故城在商州上洛縣南三十一里。荊州記云昔漢高祖入秦，王陵起兵丹水以應之，此城王陵所築，因名。」"}]},{"id":"a194","section":"元年","anchor":"王吸出武關，因王陵兵南陽，以迎太公、呂后於沛。楚聞之，發兵距之陽夏，","notes":[{"source":"索隱","text":"韋昭云：「縣名，屬淮陽，後屬陳。夏音更雅反。」"}]},{"id":"a195","section":"二年","anchor":"王申陽皆降。韓王昌不聽，使韓信擊破之。於是置隴西、北地、上郡、渭南、","notes":[{"source":"集解","text":"徐廣曰：「後曰京兆。」"}]},{"id":"a196","section":"二年","anchor":"皆降。韓王昌不聽，使韓信擊破之。於是置隴西、北地、上郡、渭南、河上、","notes":[{"source":"集解","text":"徐廣曰：「馮翊。」"}]},{"id":"a197","section":"二年","anchor":"王昌不聽，使韓信擊破之。於是置隴西、北地、上郡、渭南、河上、中地郡；","notes":[{"source":"集解","text":"徐廣曰：「扶風。」"}]},{"id":"a198","section":"二年","anchor":"信擊破之。於是置隴西、北地、上郡、渭南、河上、中地郡；關外置河南郡。","notes":[{"source":"集解","text":"徐廣曰：「十月，漢王至陝。」"}]},{"id":"a199","section":"二年","anchor":"郡。更立韓太尉信爲韓王。諸將以萬人若以一郡降者，封萬戶。繕治河上塞。","notes":[{"source":"集解","text":"晉灼曰：「晁錯傳秦時北攻胡，築河上塞。」"}]},{"id":"a200","section":"二年","anchor":"渡，魏王豹將兵從。下河內，虜殷王，置河內郡。南渡平陰津，至雒陽。新城","notes":[{"source":"正義","text":"《括地志》云：「洛州伊闕縣在州南七十里，本漢新城也。隋文帝改新城爲伊闕，取伊闕山爲名也。」"}]},{"id":"a201","section":"二年","anchor":"。下河內，虜殷王，置河內郡。南渡平陰津，至雒陽。新城三老董公遮說漢王","notes":[{"source":"正義","text":"《百官表》云：「十里一亭，亭有長。十亭一鄉，鄉有三老，三老掌教化。」皆秦制也。又樂產云：「橫道自言曰遮。」《楚漢春秋》云：「董公八十二，遂封爲成侯。」"}]},{"id":"a202","section":"二年","anchor":"平陰津，至雒陽。新城三老董公遮說漢王以義帝死故。漢王聞之，袒而大哭。","notes":[{"source":"集解","text":"如淳曰：「袒亦如禮袒踊。」"}]},{"id":"a203","section":"二年","anchor":"帝於江南，大逆無道。寡人親爲發喪，諸侯皆縞素。悉發關內兵，收三河士，","notes":[{"source":"集解","text":"韋昭曰：「河南、河東、河內。」"}]},{"id":"a204","section":"二年","anchor":"無道。寡人親爲發喪，諸侯皆縞素。悉發關內兵，收三河士，南浮江漢以下，","notes":[{"source":"正義","text":"南收三河士，發關內兵，從雍州入子午道，至漢中，歷漢水而下，從是東行，至徐州，擊楚。"}]},{"id":"a205","section":"二年","anchor":"是時項王北擊齊，田榮與戰城陽。田榮敗，走平原，","notes":[{"source":"正義","text":"德州平原縣是。"}]},{"id":"a206","section":"二年","anchor":"之而擊漢。漢王以故得劫五諸侯兵，遂入彭城。項羽聞之，乃引兵去齊，從魯","notes":[{"source":"正義","text":"兗州曲阜也。"}]},{"id":"a207","section":"二年","anchor":"。漢王以故得劫五諸侯兵，遂入彭城。項羽聞之，乃引兵去齊，從魯出胡陵，","notes":[{"source":"正義","text":"《地理志》云胡陵在山陽郡。"}]},{"id":"a208","section":"二年","anchor":"以故得劫五諸侯兵，遂入彭城。項羽聞之，乃引兵去齊，從魯出胡陵，至蕭，","notes":[{"source":"正義","text":"徐州蕭縣。"}]},{"id":"a209","section":"二年","anchor":"遂入彭城。項羽聞之，乃引兵去齊，從魯出胡陵，至蕭，與漢大戰彭城靈壁東","notes":[{"source":"正義","text":"在徐州符離縣西北九十里。"}]},{"id":"a210","section":"二年","anchor":"呂后兄周呂侯爲漢將兵，居下邑。","notes":[{"source":"集解","text":"徐廣曰：「在梁。」"}]},{"id":"a211","section":"二年","anchor":"侯爲漢將兵，居下邑。漢王從之，稍收士卒，軍碭。漢王乃西過梁地，至虞。","notes":[{"source":"集解","text":"徐廣曰：「在梁。」"}]},{"id":"a212","section":"二年","anchor":"名廢丘爲槐里。於是令祠官祀天地四方上帝山川，以時祀之。興關內卒乘塞。","notes":[{"source":"集解","text":"李奇曰：「乘，守也。」"}]},{"id":"a213","section":"三年","anchor":"，豹不聽。漢王遣將軍韓信擊，大破之，虜豹。遂定魏地，置三郡，曰河東、","notes":[{"source":"正義","text":"今蒲州也。"}]},{"id":"a214","section":"三年","anchor":"聽。漢王遣將軍韓信擊，大破之，虜豹。遂定魏地，置三郡，曰河東、太原、","notes":[{"source":"正義","text":"今并州。"}]},{"id":"a215","section":"三年","anchor":"王遣將軍韓信擊，大破之，虜豹。遂定魏地，置三郡，曰河東、太原、上黨。","notes":[{"source":"正義","text":"今潞州。"}]},{"id":"a216","section":"三年","anchor":"漢王軍滎陽南，築甬道","notes":[{"source":"正義","text":"甬音勇。韋昭云：「起土築牆，中閒爲道。」應劭云：「恐敵抄輜重，故築垣牆如街巷。」"}]},{"id":"a217","section":"三年","anchor":"漢王軍滎陽南，築甬道屬之河，以取敖倉。","notes":[{"source":"正義","text":"孟康云：「敖，地名，在滎陽西北山上，臨河，有大倉。」太康《地理志》云：「秦建敖倉於成皋。」"}]},{"id":"a218","section":"三年","anchor":"從者，盡在城中。周苛、樅公相謂曰：「反國之王，難與守城。」因殺魏豹。","notes":[{"source":"集解","text":"徐廣曰：「案月表，三年七月，王出滎陽。八月，殺魏豹。而又云四年三月，周苛死。四月，魏豹死。二者不同。項羽殺紀信、周苛、樅公，皆是三年中。」"}]},{"id":"a219","section":"三年","anchor":"備者多，力分，漢得休，復與之戰，破楚必矣。」漢王從其計，出軍宛葉閒，","notes":[{"source":"正義","text":"宛，於元反。葉，式涉反。宛，鄧州縣也。葉，汝州縣。水經注云：「本楚惠王封諸梁子兼，號曰葉城，即子高之故邑也。」"}]},{"id":"a220","section":"三年","anchor":"漢王跳，","notes":[{"source":"集解","text":"徐廣曰：「音逃。」"},{"source":"索隱","text":"如淳曰：「跳，走也。」晉灼按：劉澤傳「跳驅至長安」。說文音徒調反。通俗文云「超通爲跳」。"}]},{"id":"a221","section":"三年","anchor":"漢王跳，獨與滕公","notes":[{"source":"索隱","text":"夏侯嬰爲滕令，故曰滕公也。"}]},{"id":"a222","section":"三年","anchor":"漢王跳，獨與滕公共車出成皋玉門，","notes":[{"source":"集解","text":"徐廣曰：「項羽紀云北門名玉門。」"}]},{"id":"a223","section":"三年","anchor":"趙地，使韓信東擊齊。漢王得韓信軍，則復振。引兵臨河，南饗軍小脩武南，","notes":[{"source":"集解","text":"晉灼曰：「在大脩武城東。」"}]},{"id":"a224","section":"三年","anchor":"欲復戰。郎中鄭忠乃說止漢王，使高壘深塹，勿與戰。漢王聽其計，使盧綰、","notes":[{"source":"集解","text":"蘇林曰：「綰音以繩綰結物之『綰』。」"}]},{"id":"a225","section":"三年","anchor":"深塹，勿與戰。漢王聽其計，使盧綰、劉賈將卒二萬人，騎數百，渡白馬津，","notes":[{"source":"索隱","text":"即黎陽津也。南界東郡白馬縣。"}]},{"id":"a226","section":"三年","anchor":"、劉賈將卒二萬人，騎數百，渡白馬津，入楚地，與彭越復擊破楚軍燕郭西，","notes":[{"source":"索隱","text":"故南燕國也。在東郡，秦以爲縣。"}]},{"id":"a227","section":"三年","anchor":"生，東走高密。項羽聞韓信已舉河北兵破齊、趙，且欲擊楚，則使龍且、周蘭","notes":[{"source":"集解","text":"徐廣曰：「一作『簡』。」"}]},{"id":"a228","section":"四年","anchor":"四年，項羽乃謂海春侯大司馬曹咎曰：「謹守成皋。若漢挑戰，","notes":[{"source":"正義","text":"挑，田弔反。下同。"}]},{"id":"a229","section":"四年","anchor":"，下之。漢果數挑楚軍，楚軍不出，使人辱之五六日，大司馬怒，度兵汜水。","notes":[{"source":"正義","text":"汜音祀，在成皋故城東。"}]},{"id":"a230","section":"四年","anchor":"韓信已破齊，使人言曰：「齊邊楚，","notes":[{"source":"集解","text":"文穎曰：「邊，近也。」"}]},{"id":"a231","section":"四年","anchor":"之。留侯曰：「不如因而立之，使自爲守。」乃遣張良操印綬立韓信爲齊王。","notes":[{"source":"集解","text":"徐廣曰：「三月。」"}]},{"id":"a232","section":"四年","anchor":"。漢王數項羽曰：「始與項羽俱受命懷王，曰先入定關中者王之，項羽負約，","notes":[{"source":"索隱","text":"負音佩也。"}]},{"id":"a233","section":"四年","anchor":"中者王之，項羽負約，王我於蜀漢，罪一。項羽矯殺卿子冠軍而自尊，罪二。","notes":[{"source":"集解","text":"徐廣曰：「卿，一作『慶』。」"},{"source":"索隱","text":"韋昭云：「宋義之號。」如淳曰：「卿者，大夫之尊；子者，子男之爵；冠軍，人之首也。尊宋義，故加此號。」"}]},{"id":"a234","section":"四年","anchor":"王子嬰，罪五。詐阬秦子弟新安二十萬，王其將，罪六。項羽皆王諸將善地，","notes":[{"source":"索隱","text":"謂章邯等。"}]},{"id":"a235","section":"四年","anchor":"。詐阬秦子弟新安二十萬，王其將，罪六。項羽皆王諸將善地，而徙逐故主，","notes":[{"source":"索隱","text":"謂田市、趙歇、韓廣之屬。"}]},{"id":"a236","section":"四年","anchor":"擊殺項羽，何苦乃與公挑戰！」項羽大怒，伏弩射中漢王。漢王傷匈，乃捫足","notes":[{"source":"索隱","text":"捫，摸也。中匈而捫足者，蓋以矢初中痛悶，不知所在故爾。或者中匈而捫足，權以安士卒之心也。"}]},{"id":"a237","section":"四年","anchor":"病創臥，張良彊請漢王起行勞軍，以安士卒，毋令楚乘勝於漢。漢王出行軍，","notes":[{"source":"正義","text":"行，寒孟反。"}]},{"id":"a238","section":"四年","anchor":"，張良彊請漢王起行勞軍，以安士卒，毋令楚乘勝於漢。漢王出行軍，病甚，","notes":[{"source":"索隱","text":"按：三輔故事曰「楚漢相距於京索閒六年，身被大創十二，矢石通中過者有四」。言漢王病創也。"}]},{"id":"a239","section":"四年","anchor":"病愈，西入關，至櫟陽，存問父老，置酒，梟故塞王欣頭櫟陽市。","notes":[{"source":"索隱","text":"梟，縣首於木也。欣自剄於汜水上，令梟之於櫟陽者，以舊都，故梟以示之也。"}]},{"id":"a240","section":"四年","anchor":"楚。項羽恐，乃與漢王約，中分天下，割鴻溝而西者爲漢，鴻溝而東者爲楚。","notes":[{"source":"索隱","text":"應劭云：「在滎陽東南三十里，蓋引河東南入淮泗也。」張華云：「一渠東南流，經浚儀，是始皇所鑿，引河灌大梁，謂之鴻溝。一渠東經陽武南，爲官渡水。」北征記云中牟臺下臨汴水，是爲官渡水也。"}]},{"id":"a241","section":"四年","anchor":"壁，深塹而守之。用張良計，於是韓信、彭越皆往。及劉賈入楚地，圍壽春，","notes":[{"source":"正義","text":"今壽州。"}]},{"id":"a242","section":"四年","anchor":"之。用張良計，於是韓信、彭越皆往。及劉賈入楚地，圍壽春，漢王敗固陵，","notes":[{"source":"集解","text":"晉灼曰：「即固始。」"}]},{"id":"a243","section":"四年","anchor":"賈入楚地，圍壽春，漢王敗固陵，乃使使者召大司馬周殷舉九江兵而迎（之）","notes":[{"source":"集解","text":"徐廣曰：「周殷以兵隨劉賈。」"}]},{"id":"a244","section":"四年","anchor":"，漢王敗固陵，乃使使者召大司馬周殷舉九江兵而迎（之）武王，行屠城父，","notes":[{"source":"正義","text":"父音甫，今亳州縣。"}]},{"id":"a245","section":"四年","anchor":"舉九江兵而迎（之）武王，行屠城父，隨（何）劉賈、齊梁諸侯皆大會垓下。","notes":[{"source":"集解","text":"徐廣曰：「七月。」"}]},{"id":"a246","section":"五年","anchor":"將軍在皇帝後。項羽之卒可十萬。淮陰先合，不利，卻。孔將軍、費將軍縱，","notes":[{"source":"正義","text":"二人韓信將也。縱兵擊項羽也。以「縱」字爲絕句。孔將軍，蓼侯孔熙。費將軍，費侯陳賀也。"}]},{"id":"a247","section":"五年","anchor":"十萬。淮陰先合，不利，卻。孔將軍、費將軍縱，楚兵不利，淮陰侯復乘之，","notes":[{"source":"正義","text":"復，扶富反。乘猶登也，進也。"}]},{"id":"a248","section":"五年","anchor":"軍、費將軍縱，楚兵不利，淮陰侯復乘之，大敗垓下。項羽卒聞漢軍之楚歌，","notes":[{"source":"索隱","text":"應劭云：「今雞鳴歌也。」顏遊秦云：「楚歌猶吳謳也。」按：高祖令戚夫人楚舞，自爲楚歌，是楚人之歌聲也。"}]},{"id":"a249","section":"五年","anchor":"，以爲漢盡得楚地，項羽乃敗而走，是以兵大敗。使騎將灌嬰追殺項羽東城，","notes":[{"source":"集解","text":"徐廣曰：「十二月。」"}]},{"id":"a250","section":"五年","anchor":"等以死守之。」漢王三讓，不得已，曰：「諸君必以爲便，便國家。」甲午，","notes":[{"source":"集解","text":"徐廣曰：「二月甲午。」"}]},{"id":"a251","section":"五年","anchor":"讓，不得已，曰：「諸君必以爲便，便國家。」甲午，乃即皇帝位氾水之陽。","notes":[{"source":"集解","text":"蔡邕曰：「上古天子稱皇，其次稱帝，其次稱王。秦承三王之末，爲漢驅除，自以德兼三皇、五帝，故并以爲號。漢高祖受命，功德宜之，因而不改。」"},{"source":"正義","text":"氾音敷劍反。《括地志》云：「高祖即位壇在曹州濟陰縣界。張晏曰『氾水在濟陰界，取其氾愛弘大而潤下』。」"}]},{"id":"a252","section":"五年","anchor":"皇帝曰義帝無後。齊王韓信習楚風俗，徙爲楚王，都下邳。","notes":[{"source":"正義","text":"音被悲反，泗州下邳縣是，楚王韓信之都。"}]},{"id":"a253","section":"五年","anchor":"後。齊王韓信習楚風俗，徙爲楚王，都下邳。立建成侯彭越爲梁王，都定陶。","notes":[{"source":"正義","text":"曹州濟陰縣城是，梁王彭越之都。"}]},{"id":"a254","section":"五年","anchor":"爲楚王，都下邳。立建成侯彭越爲梁王，都定陶。故韓王信爲韓王，都陽翟。","notes":[{"source":"正義","text":"洛州陽翟縣是，韓王信之都。"}]},{"id":"a255","section":"五年","anchor":"梁王，都定陶。故韓王信爲韓王，都陽翟。徙衡山王吳芮爲長沙王，都臨湘。","notes":[{"source":"正義","text":"《括地志》云：「潭州長沙縣，本漢臨湘縣，長沙王吳芮都之。芮墓在長沙縣北四里。」"}]},{"id":"a256","section":"五年","anchor":"天下大定。高祖都雒陽，諸侯皆臣屬。故臨江王驩","notes":[{"source":"集解","text":"徐廣曰：「一作『尉』。」"}]},{"id":"a257","section":"五年","anchor":"五月，兵皆罷歸家。諸侯子在關中者復之十二歲，其歸者復之六歲，食之","notes":[{"source":"正義","text":"食音寺。"}]},{"id":"a258","section":"五年","anchor":"高祖置酒雒陽南宮。","notes":[{"source":"正義","text":"《括地志》云：「南宮在雒州雒陽縣東北二十六里洛陽故城中。《輿地志》云秦時已有南北宮。」"}]},{"id":"a259","section":"五年","anchor":"皆言其情。吾所以有天下者何？項氏之所以失天下者何？」高起、王陵對曰：","notes":[{"source":"集解","text":"孟康曰：「姓高，名起。」瓚曰：「漢帝年紀高帝時有信平侯臣陵、都武侯臣起。魏相丙吉奏事高帝時奏事有將軍臣陵、臣起。」"}]},{"id":"a260","section":"五年","anchor":"其秋，利幾反，","notes":[{"source":"正義","text":"幾音機。姓名也。項羽之將，爲陳縣令，降漢。高帝徵諸侯，利幾恐，故反。"}]},{"id":"a261","section":"五年","anchor":"爲陳公，不隨項羽，亡降高祖，高祖侯之潁川。高祖至雒陽，舉通侯籍召之，","notes":[{"source":"集解","text":"如淳曰：「得在通侯之籍。」"}]},{"id":"a262","section":"六年","anchor":"，人臣也。柰何令人主拜人臣！如此，則威重不行。」後高祖朝，太公擁篲，","notes":[{"source":"集解","text":"李奇曰：「爲恭也。如今卒持帚者也。」"}]},{"id":"a263","section":"六年","anchor":"太公曰：「帝，人主也，柰何以我亂天下法！」於是高祖乃尊太公爲太上皇。","notes":[{"source":"集解","text":"蔡邕曰：「不言帝，非天子也。」"},{"source":"索隱","text":"按：蔡邕云「不言帝，非天子也」。又按：本紀秦始皇追尊莊襄王爲太上皇，已有故事矣。蓋太上者，無上也。皇者德大於帝，欲尊其父，故號曰太上皇也。"}]},{"id":"a264","section":"六年","anchor":"，人主也，柰何以我亂天下法！」於是高祖乃尊太公爲太上皇。心善家令言，","notes":[{"source":"索隱","text":"顏氏按：荀悅云「故雖天子必有尊也，無父猶設三老，況其存乎？家令之言過矣」。晉劉寶云「善其發悟己心，因得尊崇父號也」。"}]},{"id":"a265","section":"六年","anchor":"有上變事告楚王信謀反，上問左右，左右爭欲擊之。用陳平計，乃僞遊雲夢，","notes":[{"source":"集解","text":"韋昭曰：「在南郡華容縣。」"}]},{"id":"a266","section":"六年","anchor":"計，乃僞遊雲夢，會諸侯於陳，楚王信迎，即因執之。是日，大赦天下。田肯","notes":[{"source":"索隱","text":"漢紀及《漢書》作「宵」，劉顯云相傳作「肯」也。"}]},{"id":"a267","section":"六年","anchor":"因執之。是日，大赦天下。田肯賀，因說高祖曰：「陛下得韓信，又治秦中。","notes":[{"source":"集解","text":"如淳曰：「時山東人謂關中爲秦中。」"}]},{"id":"a268","section":"六年","anchor":"大赦天下。田肯賀，因說高祖曰：「陛下得韓信，又治秦中。秦，形勝之國，","notes":[{"source":"集解","text":"張晏曰：「秦地帶山河，得形勢之勝便者。」"},{"source":"索隱","text":"韋昭云：「地形險固，故能勝人也。」"}]},{"id":"a269","section":"六年","anchor":"又治秦中。秦，形勝之國，帶河山之險，縣隔千里，持戟百萬，秦得百二焉。","notes":[{"source":"集解","text":"應劭曰：「河山之險，與諸侯相縣隔，地絕千里，所以能禽諸侯者，得天下之利百二也。」李斐曰：「河山之險，由地勢高，順流而下易，故天下於秦懸隔千里，持戟百萬，秦得百二焉。」蘇林曰：「得百中之二焉。秦地險固，二萬人足當諸侯百萬人也。」"},{"source":"索隱","text":"服虔云：「謂函谷關去長安千里爲縣隔。」按：文以河山險固形勝，其勢如隔千里也。蘇林曰：「百二，百中之二，二十萬人也。」虞喜云：「百二者，得百之二。言諸侯持戟百萬，秦地險固，一倍於天下，故云得百二焉，言倍之也，蓋言秦兵當二百萬也。『齊得十二』亦如之，故爲東西秦，言勢相敵，但立文相避，故云十二。言餘諸侯十萬，齊地形勝亦倍於他國，當二十萬人也。」"}]},{"id":"a270","section":"六年","anchor":"百萬，秦得百二焉。地埶便利，其以下兵於諸侯，譬猶居高屋之上建瓴水也。","notes":[{"source":"集解","text":"如淳曰：「瓴，盛水瓶也。居高屋之上而幡瓴水，言其向下之勢易也。建音蹇。」晉灼曰：「許慎曰瓴，罋似瓶者。」"}]},{"id":"a271","section":"六年","anchor":"之上建瓴水也。夫齊，東有琅邪、即墨之饒，南有泰山之固，西有濁河之限，","notes":[{"source":"集解","text":"晉灼曰：「齊西有平原。河水東北過高唐，高唐即平原也。孟津號黃河故曰濁河。」"}]},{"id":"a272","section":"六年","anchor":"夫齊，東有琅邪、即墨之饒，南有泰山之固，西有濁河之限，北有勃海之利。","notes":[{"source":"索隱","text":"崔浩云：「勃，旁跌也。旁跌出者，橫在濟北，故齊都賦云海旁出爲勃，名曰勃海郡。」"}]},{"id":"a273","section":"六年","anchor":"固，西有濁河之限，北有勃海之利。地方二千里，持戟百萬，縣隔千里之外，","notes":[{"source":"索隱","text":"以言齊境闊不啻千里，故云「之外」也。"}]},{"id":"a274","section":"六年","anchor":"之限，北有勃海之利。地方二千里，持戟百萬，縣隔千里之外，齊得十二焉。","notes":[{"source":"集解","text":"應劭曰：「齊得十之二，故齊湣王稱東帝。後復歸之，卒爲秦所滅者，利鈍之勢異也。」李斐曰：「齊有山河之限，地方二千里，是與天下縣隔也。設有持戟百萬之眾，齊得十中之二焉。百萬十分之二，亦二十萬也。但文相避耳。故言東西秦，其勢亦敵也。」蘇林曰：「十二，得十中之二，二十萬人當百萬。言齊雖固，不如秦二萬乃當百萬。」"}]},{"id":"a275","section":"六年","anchor":"餘日，封韓信爲淮陰侯，分其地爲二國。高祖曰將軍劉賈數有功，以爲荊王，","notes":[{"source":"索隱","text":"乃王吳地，在淮東也。姚察按：虞喜云「總言吳，別言荊者，以山命國也。今西南有荊山，在陽羨界。賈封吳地而號荊王，指取此義」。太康《地理志》陽羨縣本名荊溪。"}]},{"id":"a276","section":"六年","anchor":"淮東。弟交爲楚王，王淮西。子肥爲齊王，王七十餘城，民能齊言者皆屬齊。","notes":[{"source":"集解","text":"《漢書音義》曰：「此言時民流移，故使齊言者還齊也。」"},{"source":"正義","text":"按：言齊國形勝次於秦中，故封子肥七十餘城，近齊城邑，能齊言者咸割屬齊。親子，故大其都也。孟說恐非。"}]},{"id":"a277","section":"六年","anchor":"七十餘城，民能齊言者皆屬齊。乃論功，與諸列侯剖符行封。徙韓王信太原。","notes":[{"source":"索隱","text":"信初都陽翟也。"}]},{"id":"a278","section":"七年","anchor":"七年，匈奴攻韓王信馬邑，","notes":[{"source":"正義","text":"《搜神記》云：「昔秦人築城於武周塞以備胡，城將成而崩者數矣。有馬馳走，周旋反覆，父老異之，因依以築城，乃不崩，遂名馬邑。」《括地志》云：「朔州城，漢鴈門，即馬邑縣城也。攻韓信於馬邑，即此城。」"}]},{"id":"a279","section":"七年","anchor":"七年，匈奴攻韓王信馬邑，信因與謀反太原。白土","notes":[{"source":"集解","text":"徐廣曰：「在上郡。」"}]},{"id":"a280","section":"七年","anchor":"趙將趙利爲王以反，高祖自往擊之。會天寒，士卒墮指者什二三，遂至平城。","notes":[{"source":"正義","text":"《括地志》云：「朔州定襄縣，本漢平城縣。縣東北三十里有白登山，山上有臺，名曰白登臺。《漢書匈奴傳》云（蹋）〔冒〕頓圍高帝於白登七日，即此也。服虔曰『白登，臺名，去平城七里』。李穆叔趙記云『平城東七里有土山，高百餘尺，方十餘里。』亦謂此也。」"}]},{"id":"a281","section":"七年","anchor":"二月，高祖自平城過趙、雒陽，至長安。長樂宮成，丞相已下徙治長安。","notes":[{"source":"索隱","text":"按：漢儀注高祖六年，更名咸陽曰長安。三輔舊事扶風渭城，本咸陽地，高帝爲新城，七年屬長安也。"}]},{"id":"a282","section":"八年","anchor":"八年，高祖東擊韓王信餘反寇於東垣。","notes":[{"source":"集解","text":"《地理志》：東垣，高帝更名曰真定。"}]},{"id":"a283","section":"八年","anchor":"蕭丞相營作未央宮，","notes":[{"source":"正義","text":"《括地志》云：「未央宮在雍州長安縣西北十里長安故城中。」顏師古云：「未央殿雖南嚮，而當上書奏事謁見之徒皆詣北闕，公車司馬亦在北焉。是則以北闕爲正門，而又有東門、東闕，至於西南兩面，無門闕矣。蕭何初立未央宮，以厭勝之術理宜然乎？」按：北闕爲正者，蓋象秦作前殿，渡渭水屬之咸陽，以象天極閣道絕漢抵營室。"}]},{"id":"a284","section":"八年","anchor":"蕭丞相營作未央宮，立東闕、北闕、","notes":[{"source":"集解","text":"《關中記》曰：「東有蒼龍闕，北有玄武闕，玄武所謂北闕。」"},{"source":"索隱","text":"東闕名蒼龍，北闕名玄武，無西南二闕者，蓋蕭何以厭勝之法故不立也。說文云「闕，門觀也」。高三十丈。秦家舊處皆在渭北，而立東闕北闕，蓋取其便也。"}]},{"id":"a285","section":"八年","anchor":"高祖之東垣，過柏人，","notes":[{"source":"正義","text":"《括地志》云：「柏人故城在邢州柏人縣西北十二里。漢柏人屬趙國。」"}]},{"id":"a286","section":"八年","anchor":"謀弒高祖，高祖心動，因不留。代王劉仲弃國亡，自歸雒陽，廢以爲合陽侯。","notes":[{"source":"正義","text":"《括地志》云：「郃陽故城在同州河西縣三里。魏文侯十七年，攻秦至鄭而還築，在郃水之陽也。」"}]},{"id":"a287","section":"九年","anchor":"未央宮成。高祖大朝諸侯羣臣，置酒未央前殿。高祖奉玉卮，","notes":[{"source":"集解","text":"應劭曰：「鄉飲酒禮器也，受四升。」"}]},{"id":"a288","section":"九年","anchor":"臣，置酒未央前殿。高祖奉玉卮，起爲太上皇壽，曰：「始大人常以臣無賴，","notes":[{"source":"集解","text":"晉灼曰：「許慎曰『賴，利也』。無利入於家也。或曰江淮之閒謂小兒多狡猾爲『無賴』。」"}]},{"id":"a289","section":"十年","anchor":"越、燕王盧綰、荊王劉賈、楚王劉交、齊王劉肥、長沙王吳芮皆來朝長樂宮。","notes":[{"source":"正義","text":"《括地志》云：「秦櫟陽故宮在雍州櫟陽縣北三十五里，秦獻公所造。三輔黃圖云高祖都長安，未有宮室，居櫟陽宮也。」"}]},{"id":"a290","section":"十年","anchor":"七月，太上皇崩櫟陽宮。楚王、梁王皆來送葬。","notes":[{"source":"集解","text":"《漢書》云：「葬萬年。」"}]},{"id":"a291","section":"十年","anchor":"七月，太上皇崩櫟陽宮。楚王、梁王皆來送葬。赦櫟陽囚。更命酈邑曰新豐。","notes":[{"source":"正義","text":"麗邑，麗音力知反。《括地志》云：「新豐故城在雍州新豐縣西南四里，漢新豐宮也。太上皇時悽愴不樂，高祖竊因左右問故，答以平生所好皆屠販少年，酤酒賣餅，鬬雞蹴踘，以此爲歡，今皆無此，故不樂。高祖乃作新豐，徙諸故人實之，太上皇乃悅。」按：前于麗邑築城寺，徙其民實之，未改其名，太上皇崩後，命曰新豐。"}]},{"id":"a292","section":"十年","anchor":"八月，趙相國陳豨","notes":[{"source":"集解","text":"鄧展曰：「東海人名豬曰豨。」"}]},{"id":"a293","section":"十年","anchor":"陳豨反代地。上曰：「豨嘗爲吾使，甚有信。代地吾所急也，故封豨爲列侯，","notes":[{"source":"集解","text":"徐廣曰：「豨攻定臧荼有功，封陽夏侯。」"}]},{"id":"a294","section":"十一年","anchor":"十一年，高祖在邯鄲誅豨等未畢，豨將侯敞將萬餘人游行，王黃軍曲逆，","notes":[{"source":"集解","text":"文穎曰：「今中山蒲陰是。」"}]},{"id":"a295","section":"十一年","anchor":"年，高祖在邯鄲誅豨等未畢，豨將侯敞將萬餘人游行，王黃軍曲逆，張春渡河","notes":[{"source":"正義","text":"陳豨將也。又劉伯莊云「彼時聊城在黃河之東，王莽時乾，今濁河西北也」。今在博州西北。深丘道里記云「王莽元城人，居近河側，祖父墳墓爲水所衝，引河入深川，此王莽河因枯也。」"}]},{"id":"a296","section":"十一年","anchor":"在邯鄲誅豨等未畢，豨將侯敞將萬餘人游行，王黃軍曲逆，張春渡河擊聊城。","notes":[{"source":"集解","text":"徐廣曰：「在平原。」"},{"source":"正義","text":"《括地志》云：「故聊城在博州聊城縣西二十里。春秋時齊之西界聊，攝也。戰國時亦爲齊地。秦漢皆爲東郡之聊城也。」"}]},{"id":"a297","section":"十一年","anchor":"，王黃軍曲逆，張春渡河擊聊城。漢使將軍郭蒙與齊將擊，大破之。太尉周勃","notes":[{"source":"集解","text":"《漢書百官表》曰：「太尉，秦官。」應劭曰：「自上安下曰尉，武官悉以爲稱。」"}]},{"id":"a298","section":"十一年","anchor":"逆，張春渡河擊聊城。漢使將軍郭蒙與齊將擊，大破之。太尉周勃道太原入，","notes":[{"source":"集解","text":"韋昭曰：「道猶從。」"}]},{"id":"a299","section":"十一年","anchor":"，令出罵者斬之，不罵者原之。於是乃分趙山北，立子恆以爲代王，都晉陽。","notes":[{"source":"集解","text":"如淳曰：「文紀言都中都。又文帝過太原，復晉陽、中都二歲，似遷都於中都也。」"}]},{"id":"a300","section":"十二年","anchor":"十二年，十月，高祖已擊布軍會甀，","notes":[{"source":"集解","text":"徐廣曰：「在蘄縣西。」駰案：《漢書音義》曰「會音儈保，邑名，甀音直僞反」。"},{"source":"索隱","text":"上音鱠，下音丈僞反，地名也。《漢書》作「缶」，音作保，非也。"}]},{"id":"a301","section":"十二年","anchor":"高祖還歸，過沛，留。置酒沛宮，","notes":[{"source":"正義","text":"《括地志》云：「沛宮故地在徐州沛縣東南二十里一步。」"}]},{"id":"a302","section":"十二年","anchor":"。置酒沛宮，悉召故人父老子弟縱酒，發沛中兒得百二十人，教之歌。酒酣，","notes":[{"source":"集解","text":"應劭曰：「不醒不醉曰酣。一曰酣，洽也。」"}]},{"id":"a303","section":"十二年","anchor":"，悉召故人父老子弟縱酒，發沛中兒得百二十人，教之歌。酒酣，高祖擊筑，","notes":[{"source":"集解","text":"韋昭曰：「筑，古樂，有弦，擊之不鼓。」"},{"source":"正義","text":"音竹。應劭云：「狀似瑟而大，頭安弦，以竹擊之，故名曰筑。」顏師古云：「今筑形似瑟而小，細項。」"}]},{"id":"a304","section":"十二年","anchor":"雖都關中，萬歲後吾魂魄猶樂思沛。且朕自沛公以誅暴逆，遂有天下，其以沛","notes":[{"source":"集解","text":"《風俗通義》曰：「《漢書注》，沛人語初發聲皆言『其』。其者，楚言也。高祖始登位，教令言『其』，後以爲常耳。」"}]},{"id":"a305","section":"十二年","anchor":"留高祖。高祖曰：「吾人眾多，父兄不能給。」乃去。沛中空縣皆之邑西獻。","notes":[{"source":"集解","text":"如淳曰：「獻牛酒。」"}]},{"id":"a306","section":"十二年","anchor":"：「吾人眾多，父兄不能給。」乃去。沛中空縣皆之邑西獻。高祖復留止，張","notes":[{"source":"集解","text":"張晏曰：「張，帷帳。」"},{"source":"正義","text":"音張亮反。"}]},{"id":"a307","section":"十二年","anchor":"特爲其以雍齒故反我爲魏。」沛父兄固請，乃并復豐，比沛。於是拜沛侯劉濞","notes":[{"source":"集解","text":"服虔曰：「濞音帔。」"}]},{"id":"a308","section":"十二年","anchor":"漢將別擊布軍洮水南北，","notes":[{"source":"集解","text":"徐廣曰：「洮音道，在江淮閒。」"}]},{"id":"a309","section":"十二年","anchor":"樊噲別將兵定代，斬陳豨當城。","notes":[{"source":"索隱","text":"代之縣名也。"},{"source":"正義","text":"《括地志》云：「當城在朔州定襄縣界。土地十三州記云『當城在高柳東八十里，縣當常山，故曰當城』。」"}]},{"id":"a310","section":"十二年","anchor":"十一月，高祖自布軍至長安。十二月，高祖曰：「秦始皇帝、楚隱王","notes":[{"source":"索隱","text":"系家作「幽王」，名擇，負芻之兄。"}]},{"id":"a311","section":"十二年","anchor":"高祖自布軍至長安。十二月，高祖曰：「秦始皇帝、楚隱王陳涉、魏安釐王、","notes":[{"source":"索隱","text":"史闕名。昭王之子，王假之祖也。"}]},{"id":"a312","section":"十二年","anchor":"軍至長安。十二月，高祖曰：「秦始皇帝、楚隱王陳涉、魏安釐王、齊緡王、","notes":[{"source":"索隱","text":"名地，宣王子，王建祖。"}]},{"id":"a313","section":"十二年","anchor":"。十二月，高祖曰：「秦始皇帝、楚隱王陳涉、魏安釐王、齊緡王、趙悼襄王","notes":[{"source":"索隱","text":"名偃，孝成王丹之子，幽王遷之父也。"}]},{"id":"a314","section":"十二年","anchor":"赦之。陳豨降將言豨反時，燕王盧綰使人之豨所，與陰謀。上使辟陽侯迎綰，","notes":[{"source":"正義","text":"審食其也。《括地志》云：「辟陽故城在冀州信都縣西三十五里，漢舊縣。」"}]},{"id":"a315","section":"十二年","anchor":"四月甲辰，高祖崩長樂宮。","notes":[{"source":"集解","text":"皇甫謐曰：「高祖以秦昭王五十一年生，至漢十二年，年六十二。」"}]},{"id":"a316","section":"十二年","anchor":"臣，此常怏怏，今乃事少主，非盡族是，天下不安。」人或聞之，語酈將軍。","notes":[{"source":"集解","text":"《漢書》曰酈商。"}]},{"id":"a317","section":"十二年","anchor":"丙寅，葬。","notes":[{"source":"集解","text":"徐廣曰五月。"}]},{"id":"a318","section":"十二年","anchor":"丙寅，葬。己巳，立太子，","notes":[{"source":"正義","text":"丙寅葬，後四日至己巳，即立太子爲帝。有本脫「己」字者，妄引《漢書》云「已下」者，非。"}]},{"id":"a319","section":"十二年","anchor":"丙寅，葬。己巳，立太子，至太上皇廟。","notes":[{"source":"正義","text":"三輔黃圖云：「太上皇廟在長安城香室南，馮翊府北。」《括地志》云：「漢太上皇廟在雍州長安縣西北長安故城中酒池之北，高帝廟北。高帝廟亦在故城中也。」"}]},{"id":"a320","section":"十二年","anchor":"及孝惠五年，思高祖之悲樂沛，以沛宮爲高祖原廟。","notes":[{"source":"集解","text":"徐廣曰：「光武紀云『上幸豐，祠高祖於原廟』。」駰案：謂「原」者，再也。先既已立廟，今又再立，故謂之原廟。"}]},{"id":"a321","section":"十二年","anchor":"太史公曰：夏之政忠。忠之敝，小人以野，","notes":[{"source":"集解","text":"鄭玄曰：「忠，質厚也。野，少禮節也。」"}]},{"id":"a322","section":"十二年","anchor":"公曰：夏之政忠。忠之敝，小人以野，故殷人承之以敬。敬之敝，小人以鬼，","notes":[{"source":"集解","text":"鄭玄曰：「多威儀，如事鬼神。」"}]},{"id":"a323","section":"十二年","anchor":"故殷人承之以敬。敬之敝，小人以鬼，故周人承之以文。文之敝，小人以僿，","notes":[{"source":"集解","text":"徐廣曰：「一作『薄』。」駰案：《史記音隱》曰「僿音西志反」。鄭玄曰「文，尊卑之差也。薄，苟習文法，無悃誠也」。"},{"source":"索隱","text":"鄭音先代反，鄒本作「薄」，音扶各反，本一作「僿」，而徐廣云一作「薄」，是本互不同也。然此語本出子思子，見今禮表記，作「薄」，故鄭玄注云「文，尊卑之差也。薄，苟習文法，不悃誠也」。裴又引《音隱》云「僿音先志反」，僿塞聲相近故也。蓋僿猶薄之義也。"}]},{"id":"a324","section":"十二年","anchor":"敬之敝，小人以鬼，故周人承之以文。文之敝，小人以僿，故救僿莫若以忠。","notes":[{"source":"集解","text":"鄭玄曰：「復反始。」"}]},{"id":"a325","section":"十二年","anchor":"漢興，承敝易變，使人不倦，得天統矣。朝以十月。車服黃屋左纛。葬長陵。","notes":[{"source":"集解","text":"皇甫謐曰：「長陵山東西廣百二十步，高十三丈，在渭水北，去長安城三十五里。」"},{"source":"正義","text":"《括地志》云：「長陵在雍州咸陽縣東三十里。」"}]}]'),s=[],r={id:"008",volume:8,sanjiazhuSourceUrl:t,originalSourceUrl:e,annotations:o,criticalNotes:s};export{o as annotations,s as criticalNotes,r as default,c as id,e as originalSourceUrl,t as sanjiazhuSourceUrl,n as volume};
